__global__ __launch_bounds__(32, 1)
void l2_latency_kernel(const uint32_t *stride,
                       uint32_t *ret,
                       uint32_t *clk) {
    const char *ldg_ptr = reinterpret_cast<const char *>(stride + threadIdx.x);
    uint32_t val;

    // populate TLB
    asm volatile (
        "ld.global.cg.b32 %0, [%1];\n"
        : "=r"(val)
        : "l"(ldg_ptr)
        : "memory"
    );

    ldg_ptr += val;

    uint32_t start;
    uint32_t stop;

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(start) : : "memory"
    );

    #pragma unroll
    for (int i = 0; i < ROUND; ++i) {
        asm volatile (
            "ld.global.cg.b32 %0, [%1];\n"
            : "=r"(val)
            : "l"(ldg_ptr)
            : "memory"
        );

        /*
         * dependent LDG instructions to make sure that
         * LDG latency can not be hidden by parallel LDG.
         *
         * IADD/IMAD/XMAD's latency is much lower than
         * l2 cache and can be ignored.
         */
        ldg_ptr += val;
    }

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(stop) : : "memory"
    );

    clk[threadIdx.x] = stop - start;

    // dummy write back
    if (val == 0) {
        *ret = val;
    }
}

__global__ __launch_bounds__(THREAD, 1)
void l1_latency_kernel(void **ptr, void **ret, uint32_t *clk) {
    void **ldg_ptr = ptr + threadIdx.x;

    // warm up to populate l1 cache
    for (int i = 0; i < ROUND; ++i) {
        asm volatile (
            "ld.global.nc.b64 %0, [%0];\n"
            : "+l"(ldg_ptr) : : "memory"
        );
    }

    uint32_t start;
    uint32_t stop;

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(start) : : "memory"
    );

    for (int i = 0; i < ROUND; ++i) {
        /*
         * dependent LDG instructions to make sure that
         * LDG latency can not be hidden by parallel LDG.
         */
        asm volatile (
            "ld.global.nc.b64 %0, [%0];\n"
            : "+l"(ldg_ptr) : : "memory"
        );
    }

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(stop) : : "memory"
    );

    clk[threadIdx.x] = stop - start;

    // dummy write back
    if (ldg_ptr == nullptr) {
        *ret = ldg_ptr;
    }
}

