__global__ void sgemm_original(float *A, float *B, float *C, int n, float a, float b) {
  int j = blockIdx.x * blockDim.x + threadIdx.x;
  int i = blockIdx.y * blockDim.y + threadIdx.y;
  if( (i<n) && (j<n) ){
    float tmp = b*C[i*n+j];
    for(int k=0; k<n; k++){
      tmp += a*A[i*n+k]*B[k*n+j];
    }
    C[i*n+j]=tmp;
  }
}

