__global__ void mergeElementaryIntervalsKernel(uint *d_DstKey,
                                               uint *d_DstVal,
                                               uint *d_SrcKey,
                                               uint *d_SrcVal,
                                               uint *d_LimitsA,
                                               uint *d_LimitsB,
                                               uint  stride,
                                               uint  N)
{
    // Handle to thread block group
    cg::thread_block cta = cg::this_thread_block();
    __shared__ uint  s_key[2 * SAMPLE_STRIDE];
    __shared__ uint  s_val[2 * SAMPLE_STRIDE];

    const uint intervalI   = blockIdx.x & ((2 * stride) / SAMPLE_STRIDE - 1);
    const uint segmentBase = (blockIdx.x - intervalI) * SAMPLE_STRIDE;
    d_SrcKey += segmentBase;
    d_SrcVal += segmentBase;
    d_DstKey += segmentBase;
    d_DstVal += segmentBase;

    // Set up threadblock-wide parameters
    __shared__ uint startSrcA, startSrcB, lenSrcA, lenSrcB, startDstA, startDstB;

    if (threadIdx.x == 0) {
        uint segmentElementsA = stride;
        uint segmentElementsB = umin(stride, N - segmentBase - stride);
        uint segmentSamplesA  = getSampleCount(segmentElementsA);
        uint segmentSamplesB  = getSampleCount(segmentElementsB);
        uint segmentSamples   = segmentSamplesA + segmentSamplesB;

        startSrcA    = d_LimitsA[blockIdx.x];
        startSrcB    = d_LimitsB[blockIdx.x];
        uint endSrcA = (intervalI + 1 < segmentSamples) ? d_LimitsA[blockIdx.x + 1] : segmentElementsA;
        uint endSrcB = (intervalI + 1 < segmentSamples) ? d_LimitsB[blockIdx.x + 1] : segmentElementsB;
        lenSrcA      = endSrcA - startSrcA;
        lenSrcB      = endSrcB - startSrcB;
        startDstA    = startSrcA + startSrcB;
        startDstB    = startDstA + lenSrcA;
    }

    // Load main input data
    cg::sync(cta);

    if (threadIdx.x < lenSrcA) {
        s_key[threadIdx.x + 0] = d_SrcKey[0 + startSrcA + threadIdx.x];
        s_val[threadIdx.x + 0] = d_SrcVal[0 + startSrcA + threadIdx.x];
    }

    if (threadIdx.x < lenSrcB) {
        s_key[threadIdx.x + SAMPLE_STRIDE] = d_SrcKey[stride + startSrcB + threadIdx.x];
        s_val[threadIdx.x + SAMPLE_STRIDE] = d_SrcVal[stride + startSrcB + threadIdx.x];
    }

    // Merge data in shared memory
    cg::sync(cta);
    merge<sortDir>(s_key,
                   s_val,
                   s_key + 0,
                   s_val + 0,
                   s_key + SAMPLE_STRIDE,
                   s_val + SAMPLE_STRIDE,
                   lenSrcA,
                   SAMPLE_STRIDE,
                   lenSrcB,
                   SAMPLE_STRIDE,
                   cta);

    // Store merged data
    cg::sync(cta);

    if (threadIdx.x < lenSrcA) {
        d_DstKey[startDstA + threadIdx.x] = s_key[threadIdx.x];
        d_DstVal[startDstA + threadIdx.x] = s_val[threadIdx.x];
    }

    if (threadIdx.x < lenSrcB) {
        d_DstKey[startDstB + threadIdx.x] = s_key[lenSrcA + threadIdx.x];
        d_DstVal[startDstB + threadIdx.x] = s_val[lenSrcA + threadIdx.x];
    }
}

__global__ void mma_kernel(
    MMA mma,
    TensorA gA,
    TensorB gB,
    TensorC gC,
    TensorD gD) {
  using namespace cute;
  ThrMMA thr_mma = mma.get_slice(threadIdx.x);
  // MMA 路径：不使用 shared memory / TMA。
  // 每个线程直接从 global 的分区读取到寄存器 fragment（tCrA/tCrB），然后执行 gemm。
  // Allocate registers for pipelining
  Tensor tCgA = thr_mma.partition_A(gA);             // (MMA,MMA_M,MMA_K)
  Tensor tCgB = thr_mma.partition_B(gB);             // (MMA,MMA_N,MMA_K)
  Tensor tCrA = thr_mma.partition_fragment_A(gA);    // (MMA,MMA_M,MMA_K)
  Tensor tCrB = thr_mma.partition_fragment_B(gB);    // (MMA,MMA_N,MMA_K)
  Tensor tCgC = thr_mma.partition_C(gC);             // (MMA,MMA_M,MMA_N)
  Tensor tCgD = thr_mma.partition_C(gD);             // (MMA,MMA_M,MMA_N)

  // Allocate the accumulators -- same size as the projected data
  Tensor tCrAcc = thr_mma.make_fragment_C(tCgC); 
#ifdef VERBOSE
  if (thread0()) {
    printf("MMA Data Struct:\n");
    print(tCgA);
    printf("\n");
    print(tCgB);
    printf("\n");
    print(tCrA);
    printf("\n");
    print(tCrB);
    printf("\n");
    print(tCgC);
    printf("\n");
    print(tCgD);
    printf("\n");
    print(tCrAcc);
    printf("\n");
  }
#endif
  // Prepare A：把该线程负责的 A 分区搬到寄存器 fragment
  for (int i = 0; i < size(tCgA); ++i) {
    tCrA(i) = tCgA(i);
  }
  // Prepare B：把该线程负责的 B 分区搬到寄存器 fragment
  for (int i = 0; i < size(tCgB); ++i) {
    tCrB(i) = tCgB(i);
  }
  // Prepare C
  if constexpr (Accumulate) {
    for (int i = 0; i < size(tCrAcc); ++i) {
      tCrAcc(i) = tCgC(i);
    }
  } else {
    clear(tCrAcc);
  }
  // 经典 warp-level MMA（SM80）
  gemm(mma, tCrA, tCrB, tCrAcc);
  // Store D
  // 将 accumulator 写回到 global D 的分区
  for (int i = 0; i < size(tCrAcc); ++i) {
    tCgD(i) = tCrAcc(i);
  }
}

__global__ void placementNew(int *d_result)
{
    // Handle to thread block group
    cg::thread_block         cta = cg::this_thread_block();
    __shared__ unsigned char __align__(8) s_buffer[sizeof(Vector<int>)];
    __shared__ int           __align__(8) s_data[1024];
    __shared__ Vector<int> *s_vector;

    // The first thread of the block initializes the shared Vector object.
    // The placement new operator enables the Vector object and the data array top
    // be placed in shared memory.
    if (threadIdx.x == 0) {
        s_vector = new (s_buffer) Vector<int>(1024, s_data);
    }

    cg::sync(cta);

    if ((threadIdx.x & 1) == 0) {
        s_vector->push(threadIdx.x >> 1);
    }

    // Need to sync as the vector implementation does not support concurrent
    // push/pop operations.
    cg::sync(cta);

    int v;

    if (s_vector->pop(v)) {
        d_result[threadIdx.x] = v;
    }
    else {
        d_result[threadIdx.x] = -1;
    }

    // Note: deleting objects placed in shared memory is not necessary (lifetime
    // of shared memory is that of the block)
}

__global__ void wgmma_kernel(
    TiledMma mma,
    TensorA gA,
    TensorB gB,
    TensorC gC,
    TensorD gD,
    CUTLASS_GRID_CONSTANT TmaA const tmaA,
    CUTLASS_GRID_CONSTANT TmaB const tmaB) {
  using namespace cute;

   // WGMMA 路径：
   // - 先用 TMA 把 gmem 的 A/B 复制到 shared memory 的 sA/sB
   // - 通过 ClusterTransactionBarrier 等待 TMA 完成
   // - 每个线程从 shared memory 分区到自己的 fragment，然后 warp-group 执行 GMMA

  extern __shared__ __align__(128) uint8_t shared_memory[];
   // 动态 shared memory 被手动切分为：
   // [sA | sB | mbar]
   // 其中 mbar 是 cluster transaction barrier 的存储（uint64_t）。
  Tensor sA = make_tensor(make_smem_ptr(reinterpret_cast<T_IN*>(shared_memory)), SharedMemoryALayout{});
  Tensor sB = make_tensor(make_smem_ptr(reinterpret_cast<T_IN*>(shared_memory) + cosize(SharedMemoryALayout{})), SharedMemoryBLayout{});
  uint64_t* mbar = reinterpret_cast<uint64_t*>(shared_memory + sizeof(T_IN) * (cosize(SharedMemoryALayout{}) + cosize(SharedMemoryBLayout{})));

   // 由 TMA descriptor 推导“可被 TMA 访问”的张量视图（mA/mB），shape 与 gA/gB 一致。
  Tensor mA = tmaA.get_tma_tensor(shape(gA));
  Tensor mB = tmaB.get_tma_tensor(shape(gB));

   // 这里只取 slice(0)：本例 dimGrid=1 且不做多 CTA 切片。
  auto cta_tmaA = tmaA.get_slice(0);
  auto cta_tmaB = tmaB.get_slice(0);
   // partition_S：把 source（global/TMA tensor）按当前 CTA/线程的视角分区
   // partition_D：把 destination（shared tensor）按当前 CTA/线程的视角分区
  Tensor tAgA = cta_tmaA.partition_S(mA);
  Tensor tAsA = cta_tmaA.partition_D(sA);
  Tensor tBgB = cta_tmaB.partition_S(mB);
  Tensor tBsB = cta_tmaB.partition_D(sB);

  // The TMA is responsible for copying everything in mode-0 of tAsA and tBsB
   // barrier 需要知道一次 TMA transaction 会写入多少字节，用于 arrive_and_expect_tx。
  constexpr int tma_transaction_bytes = sizeof(make_tensor_like(tensor<0>(tAsA))) + sizeof(make_tensor_like(tensor<0>(tBsB)));

#ifdef VERBOSE
  if (thread0()) {
    printf("TMA Data Struct:\n");
    print(mA);
    printf("\n");
    print(mB);
    printf("\n");
    print(sA);
    printf("\n");
    print(sB);
    printf("\n");
    print(tAgA);
    printf("\n");
    print(tAsA);
    printf("\n");
    print(tBgB);
    printf("\n");
    print(tBsB);
    printf("\n");
    printf("tma_transaction_bytes: %d\n", tma_transaction_bytes);
  }
#endif

  // Initialize Barriers
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int lane_predicate = cute::elect_one_sync();
  using ProducerBarType = cutlass::arch::ClusterTransactionBarrier;
   // 只让 warp0 的一个 lane 初始化 barrier，避免重复 init。
  if ((warp_idx == 0) && lane_predicate) {
    ProducerBarType::init(mbar, 1);
  }
  cluster_sync();
  if ((warp_idx == 0) && lane_predicate) {
    // Set expected Tx Bytes after each reset / init
     // arrive_and_expect_tx：声明“接下来会有 tma_transaction_bytes 的写入”，wait 会等待计数归零。
    ProducerBarType::arrive_and_expect_tx(mbar, tma_transaction_bytes);
     // 通过 tmaA/tmaB 把 global 的分区复制到 shared 的分区，barrier 会在 transaction 完成时被满足。
    copy(tmaA.with(*mbar), tAgA, tAsA);
    copy(tmaB.with(*mbar), tBgB, tBsB);
  }
   // 等待 TMA 复制完成；此时 sA/sB 中的数据对后续 warp-group MMA 可见。
  ProducerBarType::wait(mbar, 0);

   // 每个线程从 tiled_mma 中拿到自己的 thread slice，并把 shared/global 的张量映射到寄存器可访问的分区。
  ThrMMA thr_mma = mma.get_thread_slice(threadIdx.x);
  Tensor tCsA = thr_mma.partition_A(sA);
  Tensor tCsB = thr_mma.partition_B(sB);
  Tensor tCgC = thr_mma.partition_C(gC);
  Tensor tCgD = thr_mma.partition_C(gD);

  // Allocate accumulators and clear them
   // tCrAcc：寄存器 accumulator fragment（输出 tile 对应的投影/打包形式）
  Tensor tCrAcc = thr_mma.make_fragment_C(tCgD);

  if constexpr (Accumulate) {
    for (int i = 0; i < size(tCrAcc); ++i) {
      tCrAcc(i) = tCgC(i);
    }
  } else {
    clear(tCrAcc);
  }

  // Allocate "fragments" -- Creat Descriptor
   // tCrA/tCrB：为 WGMMA 构建的寄存器 fragment/descriptor（其底层仍然指向 shared 分区 tCsA/tCsB）。
  Tensor tCrA = thr_mma.make_fragment_A(tCsA);
  Tensor tCrB = thr_mma.make_fragment_B(tCsB);

#ifdef VERBOSE
  if (thread0()) {
    printf("WGMMA Data Struct:\n");
    print(tCsA);
    printf("\n");
    print(tCsB);
    printf("\n");
    print(tCgC);
    printf("\n");
    print(tCgD);
    printf("\n");
    print(tCrA);
    printf("\n");
    print(tCrB);
    printf("\n");
  }
#endif
  // warp-group 级别的 GMMA：需要显式的 arrive/commit/wait 来保证指令批次与依赖。
  warpgroup_arrive();
  if constexpr (Accumulate) {
    mma.accumulate_ = GMMA::ScaleOut::One;
  }
  gemm(mma, tCrA(_, _, _), tCrB(_, _, _), tCrAcc);
  warpgroup_commit_batch();

  // Wait for all MMAs in a K_TILE to complete
  warpgroup_wait<0>();
  // 将 accumulator fragment 写回到 global D（tCgD 是对 gD 的分区视图）。
  for (int i = 0; i < size(tCrAcc); ++i) {
    tCgD(i) = tCrAcc(i);
  }
}

__global__ void
mixed_precision_gemm(void *Cptr, const void *Aptr, const void *Bptr, int m, int n, int k, void *Outptr) {
  using namespace cute;

  using X = Underscore;
  using OutType = typename Spec::OutType;
  using ComputeTypeA = typename Spec::ComputeTypeA;
  using ComputeTypeB = typename Spec::ComputeTypeB;
  using ComputeTypeC = typename Spec::ComputeTypeC;
  using TiledMMA = typename Spec::TiledMMA;

  constexpr int kTileM = Spec::kTileM;
  constexpr int kTileN = Spec::kTileN;
  constexpr int kTileK = Spec::kTileK;

  int tid = threadIdx.x;

  Tensor mA = make_tensor(make_gmem_ptr((ComputeTypeA *)Aptr), make_shape(m, k), make_stride(k, Int<1>{})); // (M, K)
  Tensor mB = make_tensor(make_gmem_ptr((ComputeTypeB *)Bptr), make_shape(n, k), make_stride(k, Int<1>{})); // (N, K)
  Tensor mC = make_tensor(make_gmem_ptr((ComputeTypeC *)Cptr), make_shape(m, n), make_stride(n, Int<1>{})); // (M, N)
  Tensor mO = make_tensor(make_gmem_ptr((OutType *)Outptr), make_shape(m, n), make_stride(n, Int<1>{}));    // (M, N)

  auto tiler = make_tile(Int<kTileM>{}, Int<kTileN>{}, Int<kTileK>{});
  auto coord = make_coord(0, 0, 0);

  // Define the block global tensors (static)
  Tensor gA = local_tile(mA, tiler, coord, Step<_1, X, _1>{}); // (kTileM, kTileK)
  Tensor gB = local_tile(mB, tiler, coord, Step<X, _1, _1>{}); // (kTileN, kTileK)
  Tensor gC = local_tile(mC, tiler, coord, Step<_1, _1, X>{}); // (kTileM, kTileN)
  Tensor gO = local_tile(mO, tiler, coord, Step<_1, _1, X>{}); // (kTileM, kTileN)

  TiledMMA tiled_mma;
  ThrMMA thr_mma = tiled_mma.get_slice(tid);

  Tensor tCgA = thr_mma.partition_A(gA); // (MMA, MMA_M, MMA_K)
  Tensor tCgB = thr_mma.partition_B(gB); // (MMA, MMA_N, MMA_K)
  Tensor tCgC = thr_mma.partition_C(gC); // (MMA, MMA_M, MMA_N)

  Tensor tCrA = thr_mma.partition_fragment_A(gA); // (MMA, MMA_M, MMA_K)
  Tensor tCrB = thr_mma.partition_fragment_B(gB); // (MMA, MMA_N, MMA_K)
  Tensor tCrC = thr_mma.partition_fragment_C(gC); // (MMA, MMA_M, MMA_N)

  auto copy_atom = AutoVectorizingCopy{};

  copy(copy_atom, tCgA, tCrA);
  copy(copy_atom, tCgB, tCrB);

  if constexpr (IsGemm)
    clear(tCrC); // Set the accumulators to zero
  else
    copy(copy_atom, tCgC, tCrC);

  gemm(tiled_mma, tCrC, tCrA, tCrB, tCrC);

  if constexpr (!IsCvtPrecision) {
    copy(copy_atom, tCrC, tCgC);
  } else {
    auto tCrO = make_tensor_like<OutType>(tCrC);
    copy(tCrC, tCrO); // Convert precision

    Tensor tCgO = thr_mma.partition_C(gO); // (MMA, MMA_M, MMA_N)
    copy(copy_atom, tCrO, tCgO);

    // Equivalent to:
    // Tensor tCgO = thr_mma.partition_C(gO);  // (MMA, MMA_M, MMA_N)
    // copy(copy_atom, tCrC, tCgO);

    // Equivalent to:
    // Tensor tCgO = thr_mma.partition_C(gO);  // (MMA, MMA_M, MMA_K)
    // Tensor tCrO = thr_mma.partition_fragment_C(gO);  // (MMA, MMA_M, MMA_N)
    // copy(copy_atom, tCrC, tCrO);  // Convert precision
    // copy(copy_atom, tCrO, tCgO);
  }
}

