    if (idx < N) {
        c[idx] = a[idx] + b[idx];
    }
}

__global__ void transformKernel(float *outputData, int width, int height, float theta, cudaTextureObject_t tex)
{
    // calculate normalized texture coordinates
    unsigned int x = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int y = blockIdx.y * blockDim.y + threadIdx.y;

    float u  = (float)x - (float)width / 2;
    float v  = (float)y - (float)height / 2;
    float tu = u * cosf(theta) - v * sinf(theta);
    float tv = v * cosf(theta) + u * sinf(theta);

    tu /= (float)width;
    tv /= (float)height;

    // read from texture and write to global memory
    outputData[y * width + x] = tex2D<float>(tex, tu + 0.5f, tv + 0.5f);
}

__global__ __launch_bounds__(16, 1)
void smem_latency_kernel(const uint32_t *addr, uint32_t *ret, uint32_t *clk) {
    __shared__ uint32_t smem[16];

    smem[threadIdx.x] = addr[threadIdx.x];

    uint32_t start;
    uint32_t stop;
    uint32_t smem_addr;

    asm volatile (
        "{.reg .u64 u64addr;\n"
        " cvta.to.shared.u64 u64addr, %1;\n"
        " cvt.u32.u64 %0, u64addr;}\n"
        : "=r"(smem_addr)
        : "l"(smem + threadIdx.x)
    );

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(start) : : "memory"
    );

    #pragma unroll
    for (int i = 0; i < ROUND; ++i) {
        /*
         * dependent LDS instructions to make sure that
         * LDS latency can not be hidden by parallel LDS.
         */
        asm volatile (
            "ld.shared.b32 %0, [%0];\n"
            : "+r"(smem_addr) : : "memory"
        );
    }

    asm volatile (
        "bar.sync 0;\n"
        "mov.u32 %0, %%clock;\n"
        : "=r"(stop) : : "memory"
    );

    clk[threadIdx.x] = stop - start;

    // dummy write back
    if (smem_addr == ~0x0) {
        *ret = smem_addr;
    }
}

