                                    group_modes<0, 2>(gA)); // (TMA,K_TILES) and (TMA)
  auto [tBgB, tBsB] = tma_partition(tma_B, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sB),
                                    group_modes<0, 2>(gB)); // (TMA,K_TILES) and (TMA)
