}

__global__ void filter_arr(int *dst, int *nres, const int *src, int n)
{
    int id = threadIdx.x + blockIdx.x * blockDim.x;

    for (int i = id; i < n; i += gridDim.x * blockDim.x) {
        if (src[i] > 0)
            dst[atomicAggInc(nres)] = src[i];
    }
}

__global__ void
mapToBuckets(const int *srcArr, int *indicesBuckets, int *bucketCounters, const int srcSize, const int numOfBuckets)
{
#if __CUDA_ARCH__ >= 700
    cg::grid_group grid = cg::this_grid();

    for (int i = grid.thread_rank(); i < srcSize; i += grid.size()) {
        const int bucket = srcArr[i];
        if (bucket < numOfBuckets) {
            indicesBuckets[atomicAggIncMulti(bucket, bucketCounters)] = i;
        }
    }
#endif
}

__global__ void calculateMaxInEachBuckets(const int *srcArr,
                                          const int *valueInBuckets,
                                          int       *bucketsMax,
                                          const int  srcSize,
                                          const int  numOfBuckets)
{
#if __CUDA_ARCH__ >= 700
    cg::grid_group grid = cg::this_grid();

    for (int i = grid.thread_rank(); i < srcSize; i += grid.size()) {
        const int bucket = srcArr[i];
        if (bucket < numOfBuckets) {
            atomicAggMaxMulti(bucket, bucketsMax, valueInBuckets[i]);
        }
    }
#endif
}

__global__ void d_boxfilter_rgba_y(cudaSurfaceObject_t *dstSurfMipMapArray,
                                   cudaSurfaceObject_t *srcSurfMipMapArray,
                                   size_t               baseWidth,
                                   size_t               baseHeight,
                                   size_t               mipLevels,
                                   int                  filter_radius)
{
    unsigned int x     = blockIdx.x * blockDim.x + threadIdx.x;
    float        scale = 1.0f / (float)((filter_radius << 1) + 1);

    for (uint32_t mipLevelIdx = 0; mipLevelIdx < mipLevels; mipLevelIdx++) {
        uint32_t width  = (baseWidth >> mipLevelIdx) ? (baseWidth >> mipLevelIdx) : 1;
        uint32_t height = (baseHeight >> mipLevelIdx) ? (baseHeight >> mipLevelIdx) : 1;

        if (x < width && height > filter_radius) {
            float4 t;
            // do left edge
            int          colInBytes = x * sizeof(uchar4);
            unsigned int pixFirst   = surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, 0);
            t                       = rgbaIntToFloat(pixFirst) * filter_radius;

            for (int y = 0; (y < (filter_radius + 1)) && (y < height); y++) {
                unsigned int pix = surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, y);
                t += rgbaIntToFloat(pix);
            }

            unsigned int dataB = rgbaFloatToInt(t * scale);
            surf2Dwrite(dataB, dstSurfMipMapArray[mipLevelIdx], colInBytes, 0);

            for (int y = 1; (y < filter_radius + 1) && ((y + filter_radius) < height); y++) {
                unsigned int pix =
                    surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, y + filter_radius);
                t += rgbaIntToFloat(pix);
                t -= rgbaIntToFloat(pixFirst);

                dataB = rgbaFloatToInt(t * scale);
                surf2Dwrite(dataB, dstSurfMipMapArray[mipLevelIdx], colInBytes, y);
            }

            // main loop
            for (int y = (filter_radius + 1); y < (height - filter_radius); y++) {
                unsigned int pix =
                    surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, y + filter_radius);
                t += rgbaIntToFloat(pix);

                pix = surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, y - filter_radius - 1);
                t -= rgbaIntToFloat(pix);

                dataB = rgbaFloatToInt(t * scale);
                surf2Dwrite(dataB, dstSurfMipMapArray[mipLevelIdx], colInBytes, y);
            }

            // do right edge
            unsigned int pixLast = surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, height - 1);
            for (int y = height - filter_radius; (y < height) && ((y - filter_radius - 1) > 1); y++) {
                t += rgbaIntToFloat(pixLast);
                unsigned int pix =
                    surf2Dread<unsigned int>(srcSurfMipMapArray[mipLevelIdx], colInBytes, y - filter_radius - 1);
                t -= rgbaIntToFloat(pix);
                dataB = rgbaFloatToInt(t * scale);
                surf2Dwrite(dataB, dstSurfMipMapArray[mipLevelIdx], colInBytes, y);
            }
        }
    }
}

__global__ __launch_bounds__(Spec::kThreadNum) void warp_specialization(__grid_constant__ TMA_A const tma_A,
                                                                        __grid_constant__ TMA_B const tma_B,
                                                                        __grid_constant__ TMA_C const tma_C,
                                                                        __grid_constant__ TMA_D const tma_D,
                                                                        int M,
                                                                        int N,
                                                                        int K) {
  using namespace cute;

  using X = Underscore;
  using OutType = typename Spec::OutType;
  using ComputeTypeA = typename Spec::ComputeTypeA;
  using ComputeTypeB = typename Spec::ComputeTypeB;
  using ComputeTypeC = typename Spec::ComputeTypeC;
  using SmemLayoutA = typename Spec::SmemLayoutA;
  using SmemLayoutB = typename Spec::SmemLayoutB;
  using SmemLayoutC = typename Spec::SmemLayoutC;
  using SmemLayoutD = typename Spec::SmemLayoutD;

  constexpr int kTileM = Spec::kTileM;
  constexpr int kTileN = Spec::kTileN;
  constexpr int kTileK = Spec::kTileK;
  constexpr int kStages = Spec::kStages;
  constexpr int kClusterSize = Spec::kClusterSize;
  constexpr int kProducerRegisters = Spec::kProducerRegisters;
  constexpr int kConsumerRegisters = Spec::kConsumerRegisters;
  constexpr int kNumMmaWarpGroups = Spec::kNumMmaWarpGroups;

  int tid = threadIdx.x;
  int bidx = blockIdx.x;
  int bidy = blockIdx.y;
  int NTilesK = ceil_div(K, kTileK);

  int warpgroup_idx = cutlass::canonical_warp_group_idx();
  int thread_idx_in_warpgroup = tid % cutlass::NumThreadsPerWarpGroup;
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int warp_idx_in_warp_group = warp_idx % cutlass::NumWarpsPerWarpGroup;
  int lane_idx = cutlass::canonical_lane_idx();
  int lane_predicate = cute::elect_one_sync();

  ////////////////////////////////////////////////////////////////////////////////////
  ///////////////////////////////////// Shared Memory ////////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  extern __shared__ __align__(1024) uint8_t smem_raw[];

  using SharedStorage = SharedStorage_AB<ComputeTypeA, ComputeTypeB, SmemLayoutA, SmemLayoutB>;
  SharedStorage &smem = *reinterpret_cast<SharedStorage *>(smem_raw);

  auto *Aptr_smem = smem.A.begin();
  auto *Bptr_smem = smem.B.begin();
  uint8_t *Cptr_smem = smem_raw;
  uint8_t *Dptr_smem = smem_raw;

  uint64_t *tma_load_mbarrier = smem.tma_barrier;    // ClusterTransactionBarrier
  uint64_t *mma_consume_mbarrier = smem.mma_barrier; // ClusterBarrier

  ////////////////////////////////////////////////////////////////////////////////////
  ///////////////////////////////////// Initialization ///////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  // Prefetch TMA tensor to L2 cache
  if ((warp_idx == 0) && lane_predicate) {
    cute::prefetch_tma_descriptor(tma_A.get_tma_descriptor());
    cute::prefetch_tma_descriptor(tma_B.get_tma_descriptor());
    if constexpr (!IsGemm) {
      cute::prefetch_tma_descriptor(tma_C.get_tma_descriptor());
    }
  }

  Tensor mA = tma_A.get_tma_tensor(make_shape(M, K));
  Tensor mB = tma_B.get_tma_tensor(make_shape(N, K));
  Tensor mC = tma_C.get_tma_tensor(make_shape(M, N));
  Tensor mD = tma_D.get_tma_tensor(make_shape(M, N));

  auto tiler = make_tile(Int<kTileM>{}, Int<kTileN>{}, Int<kTileK>{});
  auto coord = make_coord(bidy, bidx, _);

  Tensor gA = local_tile(mA, tiler, coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, K_TILES)
  Tensor gB = local_tile(mB, tiler, coord, Step<X, _1, _1>{}); // (BLK_N, BLK_K, K_TILES)
  Tensor gC = local_tile(mC, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)
  Tensor gD = local_tile(mD, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  Tensor sA = make_tensor(make_smem_ptr((ComputeTypeA *)Aptr_smem), SmemLayoutA{}); // (BLK_M, BLK_K, kStages)
  Tensor sB = make_tensor(make_smem_ptr((ComputeTypeB *)Bptr_smem), SmemLayoutB{}); // (BLK_N, BLK_K, kStages)
  Tensor sC = make_tensor(make_smem_ptr((ComputeTypeC *)Cptr_smem), SmemLayoutC{}); // (BLK_M, BLK_N)
  Tensor sD = make_tensor(make_smem_ptr((OutType *)Dptr_smem), SmemLayoutD{});      // (BLK_M, BLK_N)

  // Init TMA load barrier
  if ((warp_idx == 0) && lane_predicate) {
#pragma unroll
    for (int pipe = 0; pipe < kStages; ++pipe) {
      initialize_barrier(tma_load_mbarrier[pipe], /* arrival count */ 1);
      initialize_barrier(mma_consume_mbarrier[pipe], /* arrival count */ kNumMmaWarpGroups * kClusterSize);
    }
  }

  // Make initialized barrier visible across warps / cta / cluster
  cutlass::arch::fence_barrier_init();
  // Make initialized barrier visible in async proxy.
  cutlass::arch::fence_view_async_shared();

  // We need this to guarantee that the mbarrier init is visible
  // To all producers and consumer blocks in the Cluster
  if constexpr (kClusterSize > 1) {
    cute::cluster_arrive_relaxed();
    cute::cluster_wait();
  } else {
    __syncthreads();
  }

  ////////////////////////////////////////////////////////////////////////////////////
  ////////////////////////////////// Warp Specialization /////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  enum class WarpGroupRole { Producer = 0, Consumer0 = 1, Consumer1 = 2 };

  auto warpgroup_role = WarpGroupRole(warpgroup_idx);

  if (warpgroup_role == WarpGroupRole::Producer) {
    cutlass::arch::warpgroup_reg_dealloc<kProducerRegisters>();

    // Define the CTA-in-cluster Layout and Coord
    uint32_t block_rank_in_cluster = cute::block_rank_in_cluster();
    auto cta_layout_mnk = make_layout(typename Spec::ClusterShape{});
    auto cta_coord_mnk = cta_layout_mnk.get_flat_coord(block_rank_in_cluster);

    // TMA Multicast Masks
    uint16_t mcast_mask_a = create_tma_multicast_mask<0>(cta_layout_mnk, cta_coord_mnk);
    uint16_t mcast_mask_b = create_tma_multicast_mask<1>(cta_layout_mnk, cta_coord_mnk);

    auto [tAgA, tAsA] =
        tma_partition(tma_A,
                      get<0>(cta_coord_mnk),                         // The CTA coordinate along N mode of the cluster
                      make_layout(size<0>(cta_layout_mnk)),          // The CTA layout along N mode of the cluster
                      group_modes<0, 2>(sA), group_modes<0, 2>(gA)); // (TMA,K_TILES) and (TMA,kStages)
    auto [tBgB, tBsB] =
        tma_partition(tma_B,
                      get<1>(cta_coord_mnk),                         // The CTA coordinate along M mode of the cluster
                      make_layout(size<1>(cta_layout_mnk)),          // The CTA layout along M mode of the cluster
                      group_modes<0, 2>(sB), group_modes<0, 2>(gB)); // (TMA,K_TILES) and (TMA,kStages)

    constexpr int tma_transaction_bytes =
        kTileM * kTileK * sizeof(ComputeTypeA) + kTileN * kTileK * sizeof(ComputeTypeB);

    int smem_write_pipe = 0;
    int mma_phase_bit = 1;

    if ((warp_idx_in_warp_group == 0) && lane_predicate) {
      for (int pipe = 0; pipe < NTilesK; ++pipe) {
        // [[Producer Acquire]]
        if (pipe >= kStages) {
          wait_barrier(mma_consume_mbarrier[smem_write_pipe], /* phase */ mma_phase_bit);
        }

        copy(tma_A.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_a), tAgA(_, pipe), tAsA(_, smem_write_pipe));
        copy(tma_B.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_b), tBgB(_, pipe), tBsB(_, smem_write_pipe));

        // [[Producer Commit]]
        set_barrier_transaction_bytes(tma_load_mbarrier[smem_write_pipe], tma_transaction_bytes);

        ++smem_write_pipe;
        if (smem_write_pipe == kStages) {
          smem_write_pipe = 0;
          mma_phase_bit ^= 1;
        }
      }
    }
    // Producer warpgroup
  } else {
    // Consumer warpgroup
    cutlass::arch::warpgroup_reg_alloc<kConsumerRegisters>();

    int consumer_tid = thread_idx_in_warpgroup;
    if (warpgroup_role == WarpGroupRole::Consumer1) {
      consumer_tid += cutlass::NumThreadsPerWarpGroup;
    }

    auto [tCgC, tCsC] = tma_partition(tma_C, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sC),
                                      group_modes<0, 2>(gC)); // (TMA,K_TILES) and (TMA)
    auto [tDgD, tDsD] = tma_partition(tma_D, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sD),
                                      group_modes<0, 2>(gD)); // (TMA,K_TILES) and (TMA)

    typename Spec::TiledMMA tiled_mma;
    ThrMMA thr_mma = tiled_mma.get_slice(consumer_tid);

    Tensor tCrA = thr_mma.partition_fragment_A(sA); // (MMA, MMA_M, MMA_K, kStages)
    Tensor tCrB = thr_mma.partition_fragment_B(sB); // (MMA, MMA_N, MMA_K, kStages)
    Tensor tCrC = thr_mma.partition_fragment_C(sC); // (MMA, MMA_M, MMA_N)

    int smem_read_pipe = 0;
    int tma_phase_bit = 1;

    tiled_mma.accumulate_ = GMMA::ScaleOut::Zero;

    for (int ik = 0; ik < NTilesK; ++ik) {
      if (smem_read_pipe == 0) {
        tma_phase_bit ^= 1;
      }

      // [[Consumer Wait]]
      wait_barrier(tma_load_mbarrier[smem_read_pipe], /* phase */ tma_phase_bit);

      warpgroup_fence_operand(tCrC);
      warpgroup_arrive();

#pragma unroll
      for (int k_block = 0; k_block < size<2>(tCrA); ++k_block) {
        gemm(tiled_mma, tCrA(_, _, k_block, smem_read_pipe), tCrB(_, _, k_block, smem_read_pipe), tCrC);
        tiled_mma.accumulate_ = GMMA::ScaleOut::One;
      }

      warpgroup_commit_batch();
      warpgroup_wait<0>();

      // [[Consumer Release]]
      if (thread_idx_in_warpgroup < kClusterSize) {
        arrive_barrier_cluster(mma_consume_mbarrier[smem_read_pipe], thread_idx_in_warpgroup);
      }

      ++smem_read_pipe;
      smem_read_pipe = (smem_read_pipe == kStages) ? 0 : smem_read_pipe;
    }

    warpgroup_sync(kNumMmaWarpGroups);

    // Important!
    if (consumer_tid == 0) {
#pragma unroll
      for (int pipe = 0; pipe < kStages; ++pipe) {
        invalidate_barrier(tma_load_mbarrier[pipe]);
        invalidate_barrier(mma_consume_mbarrier[pipe]);
      }
    }

    warpgroup_sync(kNumMmaWarpGroups);

    //
    // EPILOGUE
    //

    if constexpr (use_tma_store_reduce_add) {
      typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
      ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(consumer_tid);
      Tensor tCrC_r2s = r2s_thr_copy_d.retile_S(tCrC);  // (CPY, CPY_M, CPY_N)
      Tensor tCsC_r2s = r2s_thr_copy_d.partition_D(sC); // (CPY, CPY_M, CPY_N)
      copy(r2s_tiled_copy_d, tCrC_r2s, tCsC_r2s);

      tma_store_fence();
      warpgroup_sync(kNumMmaWarpGroups);

      if (consumer_tid == 0) {
        copy(tma_C, tCsC, tCgC);
        tma_store_arrive();
        tma_store_wait<0>();
      }

    } else {

      if constexpr (!IsGemm) {
        // Load C matrix with TMA
        constexpr int tma_transaction_load_c_bytes = kTileM * kTileN * sizeof(ComputeTypeC);
        using SharedStorage_C = SharedStorage_C<ComputeTypeC, SmemLayoutC>;
        SharedStorage_C &smem_c = *reinterpret_cast<SharedStorage_C *>(smem_raw);
        uint64_t &tma_load_c_mbarrier = smem_c.tma_barrier[0];

        auto tCrC_load = make_tensor_like<ComputeTypeC>(tCrC);

        typename Spec::TiledCopyC_S2R s2r_tiled_copy_c;
        ThrCopy s2r_thr_copy_c = s2r_tiled_copy_c.get_slice(consumer_tid);
        Tensor tCsC_s2r = s2r_thr_copy_c.partition_S(sC);     // (CPY, CPY_M, CPY_K)
        Tensor tCrC_s2r = s2r_thr_copy_c.retile_D(tCrC_load); // (CPY, CPY_M, CPY_K)

        if (consumer_tid == 0) {
          initialize_barrier(tma_load_c_mbarrier, /* arrival thread count */ 1);
          cutlass::arch::fence_view_async_shared();

          copy(tma_C.with(tma_load_c_mbarrier), tCgC, tCsC);
          set_barrier_transaction_bytes(tma_load_c_mbarrier, tma_transaction_load_c_bytes);
        }

        warpgroup_sync(kNumMmaWarpGroups);
        wait_barrier(tma_load_c_mbarrier, /* phase */ 0);

        copy(s2r_tiled_copy_c, tCsC_s2r, tCrC_s2r);

// compute with CUDA core
#pragma unroll
        for (int i = 0; i < size(tCrC); ++i) {
          tCrC(i) = tCrC(i) + tCrC_load(i);
        }

        // Important!
        if (consumer_tid == 0) {
          invalidate_barrier(tma_load_c_mbarrier);
        }
        warpgroup_sync(kNumMmaWarpGroups);
      }

      auto tCrD = make_tensor_like<OutType>(tCrC);
      copy(tCrC, tCrD); // Convert precision

      typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
      ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(consumer_tid);
      Tensor tDrD_r2s = r2s_thr_copy_d.retile_S(tCrD);  // (CPY, CPY_M, CPY_N)
      Tensor tDsD_r2s = r2s_thr_copy_d.partition_D(sD); // (CPY, CPY_M, CPY_N)
      copy(r2s_tiled_copy_d, tDrD_r2s, tDsD_r2s);

      tma_store_fence();
      warpgroup_sync(kNumMmaWarpGroups);

      if (consumer_tid == 0) {
        copy(tma_D, tDsD, tDgD);
        tma_store_arrive();
        tma_store_wait<0>();
      }
    }
  } // consumer warp

  // https://forums.developer.nvidia.com/t/an-illegal-instruction-was-encountered/44092/8
  // __syncthreads();

  cluster_sync();
}

__global__ __launch_bounds__(Spec::kThreadNum) void
#if !(USE_CUTLASS_LAUNCHER)
    __cluster_dims__(Spec::kClusterDimX, Spec::kClusterDimY, Spec::kClusterDimZ)
#endif
        warpgroup_mma(__grid_constant__ TMA_A const tma_A,
                      __grid_constant__ TMA_B const tma_B,
                      __grid_constant__ TMA_C const tma_C,
                      __grid_constant__ TMA_D const tma_D,
                      int M,
                      int N,
                      int K) {
  using namespace cute;

  using X = Underscore;
  using OutType = typename Spec::OutType;
  using ComputeTypeA = typename Spec::ComputeTypeA;
  using ComputeTypeB = typename Spec::ComputeTypeB;
  using ComputeTypeC = typename Spec::ComputeTypeC;
  using SmemLayoutA = typename Spec::SmemLayoutA;
  using SmemLayoutB = typename Spec::SmemLayoutB;
  using SmemLayoutC = typename Spec::SmemLayoutC;
  using SmemLayoutD = typename Spec::SmemLayoutD;

  constexpr int kTileM = Spec::kTileM;
  constexpr int kTileN = Spec::kTileN;
  constexpr int kTileK = Spec::kTileK;
  constexpr int kStages = Spec::kStages;
  constexpr int kThreadNum = Spec::kThreadNum;
  constexpr int kWarpgroupNum = Spec::kWarpgroupNum;
  constexpr int kClusterSize = Spec::kClusterSize;

  extern __shared__ __align__(1024) uint8_t smem_raw[];

  using SharedStorage = SharedStorage_AB<ComputeTypeA, ComputeTypeB, SmemLayoutA, SmemLayoutB>;
  SharedStorage &smem = *reinterpret_cast<SharedStorage *>(smem_raw);

  auto *Aptr_smem = smem.A.begin();
  auto *Bptr_smem = smem.B.begin();
  uint8_t *Cptr_smem = smem_raw;
  uint8_t *Dptr_smem = smem_raw;

  int tid = threadIdx.x;
  int bidx = blockIdx.x;
  int bidy = blockIdx.y;

  Tensor mA = tma_A.get_tma_tensor(make_shape(M, K));
  Tensor mB = tma_B.get_tma_tensor(make_shape(N, K));
  Tensor mC = tma_C.get_tma_tensor(make_shape(M, N));
  Tensor mD = tma_D.get_tma_tensor(make_shape(M, N));

  auto tiler = make_tile(Int<kTileM>{}, Int<kTileN>{}, Int<kTileK>{});
  auto coord = make_coord(bidy, bidx, _);

  Tensor gA = local_tile(mA, tiler, coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, K_TILES)
  Tensor gB = local_tile(mB, tiler, coord, Step<X, _1, _1>{}); // (BLK_N, BLK_K, K_TILES)
  Tensor gC = local_tile(mC, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)
  Tensor gD = local_tile(mD, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  Tensor sA = make_tensor(make_smem_ptr((ComputeTypeA *)Aptr_smem), SmemLayoutA{}); // (BLK_M, BLK_K)
  Tensor sB = make_tensor(make_smem_ptr((ComputeTypeB *)Bptr_smem), SmemLayoutB{}); // (BLK_N, BLK_K)
  Tensor sC = make_tensor(make_smem_ptr((ComputeTypeC *)Cptr_smem), SmemLayoutC{}); // (BLK_M, BLK_N)
  Tensor sD = make_tensor(make_smem_ptr((OutType *)Dptr_smem), SmemLayoutD{});      // (BLK_M, BLK_N)

  // Define the CTA-in-cluster Layout and Coord
  uint32_t block_rank_in_cluster = cute::block_rank_in_cluster();
  auto cta_layout_mnk = make_layout(typename Spec::ClusterShape{});
  auto cta_coord_mnk = cta_layout_mnk.get_flat_coord(block_rank_in_cluster);

  // TMA Multicast Masks
  uint16_t mcast_mask_a = create_tma_multicast_mask<0>(cta_layout_mnk, cta_coord_mnk);
  uint16_t mcast_mask_b = create_tma_multicast_mask<1>(cta_layout_mnk, cta_coord_mnk);

  auto [tAgA, tAsA] = tma_partition(tma_A,
                                    get<0>(cta_coord_mnk), // The CTA coordinate along N mode of the cluster
                                    make_layout(size<0>(cta_layout_mnk)), // The CTA layout along N mode of the cluster
                                    group_modes<0, 2>(sA), group_modes<0, 2>(gA)); // (TMA,K_TILES) and (TMA,kStages)
  auto [tBgB, tBsB] = tma_partition(tma_B,
                                    get<1>(cta_coord_mnk), // The CTA coordinate along M mode of the cluster
                                    make_layout(size<1>(cta_layout_mnk)), // The CTA layout along M mode of the cluster
                                    group_modes<0, 2>(sB), group_modes<0, 2>(gB)); // (TMA,K_TILES) and (TMA,kStages)
  auto [tCgC, tCsC] = tma_partition(tma_C, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sC),
                                    group_modes<0, 2>(gC)); // (TMA,K_TILES) and (TMA)
  auto [tDgD, tDsD] = tma_partition(tma_D, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sD),
                                    group_modes<0, 2>(gD)); // (TMA,K_TILES) and (TMA)

  constexpr int tma_transaction_bytes =
      kTileM * kTileK * sizeof(ComputeTypeA) + kTileN * kTileK * sizeof(ComputeTypeB);

  typename Spec::TiledMMA tiled_mma;
  ThrMMA thr_mma = tiled_mma.get_slice(tid);

  // smem descriptors, not register fragments
  Tensor tCrA = thr_mma.partition_fragment_A(sA); // (MMA, MMA_M, MMA_K, kStages)
  Tensor tCrB = thr_mma.partition_fragment_B(sB); // (MMA, MMA_N, MMA_K, kStages)
  Tensor tCrC = thr_mma.partition_fragment_C(sC); // (MMA, MMA_M, MMA_N)
  clear(tCrC);                                    // Set the accumulators to zero

  //
  // PREFETCH
  //

  int NTilesK = ceil_div(K, kTileK);

  int warpgroup_idx = cutlass::canonical_warp_group_idx();
  int warpgroup_tid = tid % cutlass::NumThreadsPerWarpGroup;
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int lane_predicate = cute::elect_one_sync();
  uint64_t *tma_load_mbarrier = smem.tma_barrier;
  uint64_t *mma_consume_mbarrier = smem.mma_barrier;

  // Init TMA load barrier
  if ((warp_idx == 0) && lane_predicate) {
#pragma unroll
    for (int pipe = 0; pipe < kStages; ++pipe) {
      initialize_barrier(tma_load_mbarrier[pipe], /* arrival count */ 1);
      initialize_barrier(mma_consume_mbarrier[pipe], /* arrival count */ kThreadNum);
    }

    // Make initialized barrier visible in async proxy.
    cutlass::arch::fence_view_async_shared();
  }

  // Make sure all threads across all CTAs in Cluster observe barrier initialization.
  if constexpr (Spec::kClusterSize > 1) {
    cluster_sync();
  } else {
    __syncthreads();
  }

#pragma unroll
  for (int pipe = 0; pipe < kStages; ++pipe) {
    if ((warp_idx == 0) && lane_predicate && (pipe < NTilesK)) {
      copy(tma_A.with(tma_load_mbarrier[pipe], mcast_mask_a), tAgA(_, pipe), tAsA(_, pipe));
      copy(tma_B.with(tma_load_mbarrier[pipe], mcast_mask_b), tBgB(_, pipe), tBsB(_, pipe));

      // Arrive on the barrier and tell how many bytes are expected to come in.
      set_barrier_transaction_bytes(tma_load_mbarrier[pipe], tma_transaction_bytes);
    }
  }

  //
  // MAINLOOP
  //

  int gmem_read_pipe = kStages;
  int smem_write_pipe = 0;
  int smem_read_pipe = 0;
  int tma_phase_bit = 1;
  int mma_phase_bit = 1;

  for (int ik = 0; ik < NTilesK; ++ik) {
    if (smem_read_pipe == 0) {
      tma_phase_bit ^= 1;
    }
    wait_barrier(tma_load_mbarrier[smem_read_pipe], /* phase */ tma_phase_bit);

    warpgroup_fence_operand(tCrC);
    warpgroup_arrive();

    gemm(tiled_mma, tCrC, tCrA(_, _, _, smem_read_pipe), tCrB(_, _, _, smem_read_pipe), tCrC);

    warpgroup_commit_batch();
    warpgroup_wait<0>();

    arrive_barrier(mma_consume_mbarrier[smem_read_pipe]);

    ++smem_read_pipe;
    smem_read_pipe = (smem_read_pipe == kStages) ? 0 : smem_read_pipe;

    if ((warp_idx == 0) && lane_predicate && (gmem_read_pipe < NTilesK)) {
      if (smem_write_pipe == 0) {
        mma_phase_bit ^= 1;
      }
      wait_barrier(mma_consume_mbarrier[smem_write_pipe], /* phase */ mma_phase_bit);

      copy(tma_A.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_a), tAgA(_, gmem_read_pipe),
           tAsA(_, smem_write_pipe));
      copy(tma_B.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_b), tBgB(_, gmem_read_pipe),
           tBsB(_, smem_write_pipe));

      // Arrive on the barrier and tell how many bytes are expected to come in.
      set_barrier_transaction_bytes(tma_load_mbarrier[smem_write_pipe], tma_transaction_bytes);

      ++gmem_read_pipe;
      ++smem_write_pipe;
      smem_write_pipe = (smem_write_pipe == kStages) ? 0 : smem_write_pipe;
    }
  }

  __syncthreads();

  // Important!
  if ((warp_idx == 0) && lane_predicate) {
#pragma unroll
    for (int pipe = 0; pipe < kStages; ++pipe) {
      invalidate_barrier(tma_load_mbarrier[pipe]);
      invalidate_barrier(mma_consume_mbarrier[pipe]);
    }
  }
  __syncthreads();

  //
  // EPILOGUE
  //

  if constexpr (use_tma_store_reduce_add) {
    typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
    ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(tid);
    Tensor tCrC_r2s = r2s_thr_copy_d.retile_S(tCrC);  // (CPY, CPY_M, CPY_N)
    Tensor tCsC_r2s = r2s_thr_copy_d.partition_D(sC); // (CPY, CPY_M, CPY_N)
    copy(r2s_tiled_copy_d, tCrC_r2s, tCsC_r2s);

    tma_store_fence();
    __syncthreads();

    if ((warp_idx == 0) && lane_predicate) {
      copy(tma_C, tCsC, tCgC);
      tma_store_arrive();
      tma_store_wait<0>();
    }

    return;

  } else {

    if constexpr (!IsGemm) {
      // Load C matrix with TMA
      constexpr int tma_transaction_load_c_bytes = kTileM * kTileN * sizeof(ComputeTypeC);
      using SharedStorage_C = SharedStorage_C<ComputeTypeC, SmemLayoutC>;
      SharedStorage_C &smem_c = *reinterpret_cast<SharedStorage_C *>(smem_raw);
      uint64_t &tma_load_c_mbarrier = smem_c.tma_barrier[0];

      auto tCrC_load = make_tensor_like<ComputeTypeC>(tCrC);

      typename Spec::TiledCopyC_S2R s2r_tiled_copy_c;
      ThrCopy s2r_thr_copy_c = s2r_tiled_copy_c.get_slice(tid);
      Tensor tCsC_s2r = s2r_thr_copy_c.partition_S(sC);     // (CPY, CPY_M, CPY_K)
      Tensor tCrC_s2r = s2r_thr_copy_c.retile_D(tCrC_load); // (CPY, CPY_M, CPY_K)

      if ((warp_idx == 0) && lane_predicate) {
        initialize_barrier(tma_load_c_mbarrier, /* arrival thread count */ 1);
        cutlass::arch::fence_view_async_shared();

        copy(tma_C.with(tma_load_c_mbarrier), tCgC, tCsC);
        set_barrier_transaction_bytes(tma_load_c_mbarrier, tma_transaction_load_c_bytes);
      }

      __syncthreads();
      wait_barrier(tma_load_c_mbarrier, /* phase */ 0);

      copy(s2r_tiled_copy_c, tCsC_s2r, tCrC_s2r);

// compute with CUDA core
#pragma unroll
      for (int i = 0; i < size(tCrC); ++i) {
        tCrC(i) = tCrC(i) + tCrC_load(i);
      }

      // Important!
      if ((warp_idx == 0) && lane_predicate) {
        invalidate_barrier(tma_load_c_mbarrier);
      }
      __syncthreads();
    }

    auto tCrD = make_tensor_like<OutType>(tCrC);
    copy(tCrC, tCrD); // Convert precision

    typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
    ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(tid);
    Tensor tDrD_r2s = r2s_thr_copy_d.retile_S(tCrD);  // (CPY, CPY_M, CPY_N)
    Tensor tDsD_r2s = r2s_thr_copy_d.partition_D(sD); // (CPY, CPY_M, CPY_N)
    copy(r2s_tiled_copy_d, tDrD_r2s, tDsD_r2s);

    tma_store_fence();
    __syncthreads();

    if ((warp_idx == 0) && lane_predicate) {
      copy(tma_D, tDsD, tDgD);
      tma_store_arrive();
      tma_store_wait<0>();
    }
  }
}

__global__ __launch_bounds__(Spec::kThreadNum) void warp_specialization(__grid_constant__ TMA_A const tma_A,
                                                                        __grid_constant__ TMA_B const tma_B,
                                                                        __grid_constant__ TMA_C const tma_C,
                                                                        __grid_constant__ TMA_D const tma_D,
                                                                        int M,
                                                                        int N,
                                                                        int K) {
  using namespace cute;

  using X = Underscore;
  using OutType = typename Spec::OutType;
  using ComputeTypeA = typename Spec::ComputeTypeA;
  using ComputeTypeB = typename Spec::ComputeTypeB;
  using ComputeTypeC = typename Spec::ComputeTypeC;
  using SmemLayoutA = typename Spec::SmemLayoutA;
  using SmemLayoutB = typename Spec::SmemLayoutB;
  using SmemLayoutC = typename Spec::SmemLayoutC;
  using SmemLayoutD = typename Spec::SmemLayoutD;

  constexpr int kTileM = Spec::kTileM;
  constexpr int kTileN = Spec::kTileN;
  constexpr int kTileK = Spec::kTileK;
  constexpr int kStages = Spec::kStages;
  constexpr int kClusterSize = Spec::kClusterSize;
  constexpr int kProducerRegisters = Spec::kProducerRegisters;
  constexpr int kConsumerRegisters = Spec::kConsumerRegisters;
  constexpr int kNumMmaWarpGroups = Spec::kNumMmaWarpGroups;

  int tid = threadIdx.x;
  int bidx = blockIdx.x;
  int bidy = blockIdx.y;
  int NTilesK = ceil_div(K, kTileK);

  int warpgroup_idx = cutlass::canonical_warp_group_idx();
  int thread_idx_in_warpgroup = tid % cutlass::NumThreadsPerWarpGroup;
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int warp_idx_in_warp_group = warp_idx % cutlass::NumWarpsPerWarpGroup;
  int lane_idx = cutlass::canonical_lane_idx();
  int lane_predicate = cute::elect_one_sync();

  ////////////////////////////////////////////////////////////////////////////////////
  ///////////////////////////////////// Shared Memory ////////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  extern __shared__ __align__(1024) uint8_t smem_raw[];

  using SharedStorage = SharedStorage_AB<ComputeTypeA, ComputeTypeB, SmemLayoutA, SmemLayoutB>;
  SharedStorage &smem = *reinterpret_cast<SharedStorage *>(smem_raw);

  auto *Aptr_smem = smem.A.begin();
  auto *Bptr_smem = smem.B.begin();
  uint8_t *Cptr_smem = smem_raw;
  uint8_t *Dptr_smem = smem_raw;

  ////////////////////////////////////////////////////////////////////////////////////
  ///////////////////////////////////// Initialization ///////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  // Prefetch TMA tensor to L2 cache
  if ((warp_idx == 0) && lane_predicate) {
    cute::prefetch_tma_descriptor(tma_A.get_tma_descriptor());
    cute::prefetch_tma_descriptor(tma_B.get_tma_descriptor());
    if constexpr (!IsGemm) {
      cute::prefetch_tma_descriptor(tma_C.get_tma_descriptor());
    }
  }

  Tensor mA = tma_A.get_tma_tensor(make_shape(M, K));
  Tensor mB = tma_B.get_tma_tensor(make_shape(N, K));
  Tensor mC = tma_C.get_tma_tensor(make_shape(M, N));
  Tensor mD = tma_D.get_tma_tensor(make_shape(M, N));

  auto tiler = make_tile(Int<kTileM>{}, Int<kTileN>{}, Int<kTileK>{});
  auto coord = make_coord(bidy, bidx, _);

  Tensor gA = local_tile(mA, tiler, coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, K_TILES)
  Tensor gB = local_tile(mB, tiler, coord, Step<X, _1, _1>{}); // (BLK_N, BLK_K, K_TILES)
  Tensor gC = local_tile(mC, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)
  Tensor gD = local_tile(mD, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  Tensor sA = make_tensor(make_smem_ptr((ComputeTypeA *)Aptr_smem), SmemLayoutA{}); // (BLK_M, BLK_K, kStages)
  Tensor sB = make_tensor(make_smem_ptr((ComputeTypeB *)Bptr_smem), SmemLayoutB{}); // (BLK_N, BLK_K, kStages)
  Tensor sC = make_tensor(make_smem_ptr((ComputeTypeC *)Cptr_smem), SmemLayoutC{}); // (BLK_M, BLK_N)
  Tensor sD = make_tensor(make_smem_ptr((OutType *)Dptr_smem), SmemLayoutD{});      // (BLK_M, BLK_N)

  constexpr int tma_transaction_bytes =
      kTileM * kTileK * sizeof(ComputeTypeA) + kTileN * kTileK * sizeof(ComputeTypeB);

  enum class WarpGroupRole { Producer = 0, Consumer0 = 1, Consumer1 = 2 };

  auto warpgroup_role = WarpGroupRole(warpgroup_idx);

  ////////////////////////////////////////////////////////////////////////////////////
  //////////////////////////////////// Create Pipeline ///////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  using MainloopPipeline = typename cutlass::PipelineTmaAsync<kStages>;
  using PipelineState = typename MainloopPipeline::PipelineState;

  typename MainloopPipeline::Params params;
  params.transaction_bytes = tma_transaction_bytes;
  if (warpgroup_role == WarpGroupRole::Producer) {
    params.role = MainloopPipeline::ThreadCategory::Producer;
  } else {
    params.role = MainloopPipeline::ThreadCategory::Consumer;
  }
  params.is_leader = (thread_idx_in_warpgroup == 0);
  params.num_consumers = Spec::kNumMMAThreads;

  MainloopPipeline pipeline(smem.pipeline, params, typename Spec::ClusterShape{});

  cutlass::pipeline_init_arrive_relaxed(kClusterSize);

  ////////////////////////////////////////////////////////////////////////////////////
  ////////////////////////////////// Warp Specialization /////////////////////////////
  ////////////////////////////////////////////////////////////////////////////////////

  cutlass::pipeline_init_wait(kClusterSize);

  if (warpgroup_role == WarpGroupRole::Producer) {
    cutlass::arch::warpgroup_reg_dealloc<kProducerRegisters>();

    // Define the CTA-in-cluster Layout and Coord
    uint32_t block_rank_in_cluster = cute::block_rank_in_cluster();
    auto cta_layout_mnk = make_layout(typename Spec::ClusterShape{});
    auto cta_coord_mnk = cta_layout_mnk.get_flat_coord(block_rank_in_cluster);

    // TMA Multicast Masks
    uint16_t mcast_mask_a = create_tma_multicast_mask<0>(cta_layout_mnk, cta_coord_mnk);
    uint16_t mcast_mask_b = create_tma_multicast_mask<1>(cta_layout_mnk, cta_coord_mnk);

    auto [tAgA, tAsA] =
        tma_partition(tma_A,
                      get<0>(cta_coord_mnk),                         // The CTA coordinate along N mode of the cluster
                      make_layout(size<0>(cta_layout_mnk)),          // The CTA layout along N mode of the cluster
                      group_modes<0, 2>(sA), group_modes<0, 2>(gA)); // (TMA,K_TILES) and (TMA,kStages)
    auto [tBgB, tBsB] =
        tma_partition(tma_B,
                      get<1>(cta_coord_mnk),                         // The CTA coordinate along M mode of the cluster
                      make_layout(size<1>(cta_layout_mnk)),          // The CTA layout along M mode of the cluster
                      group_modes<0, 2>(sB), group_modes<0, 2>(gB)); // (TMA,K_TILES) and (TMA,kStages)

    if ((warp_idx_in_warp_group == 0) && lane_predicate) {
      PipelineState smem_write_pipe = cutlass::make_producer_start_state<PipelineState>();

      for (int pipe = 0; pipe < NTilesK; ++pipe) {
        // [[Producer Acquire]] + [[Producer Commit]]
        pipeline.producer_acquire(smem_write_pipe);

        auto *tmaBar = pipeline.producer_get_barrier(smem_write_pipe);
        copy(tma_A.with(*tmaBar, mcast_mask_a), tAgA(_, pipe), tAsA(_, smem_write_pipe.index()));
        copy(tma_B.with(*tmaBar, mcast_mask_b), tBgB(_, pipe), tBsB(_, smem_write_pipe.index()));

        ++smem_write_pipe;
      }
    }
    // Producer warpgroup
  } else {
    // Consumer warpgroup
    cutlass::arch::warpgroup_reg_alloc<kConsumerRegisters>();

    int consumer_tid = thread_idx_in_warpgroup;
    if (warpgroup_role == WarpGroupRole::Consumer1) {
      consumer_tid += cutlass::NumThreadsPerWarpGroup;
    }

    auto [tCgC, tCsC] = tma_partition(tma_C, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sC),
                                      group_modes<0, 2>(gC)); // (TMA,K_TILES) and (TMA)
    auto [tDgD, tDsD] = tma_partition(tma_D, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sD),
                                      group_modes<0, 2>(gD)); // (TMA,K_TILES) and (TMA)

    typename Spec::TiledMMA tiled_mma;
    ThrMMA thr_mma = tiled_mma.get_slice(consumer_tid);

    Tensor tCrA = thr_mma.partition_fragment_A(sA); // (MMA, MMA_M, MMA_K, kStages)
    Tensor tCrB = thr_mma.partition_fragment_B(sB); // (MMA, MMA_N, MMA_K, kStages)
    Tensor tCrC = thr_mma.partition_fragment_C(sC); // (MMA, MMA_M, MMA_N)

    PipelineState smem_read_pipe;

    tiled_mma.accumulate_ = GMMA::ScaleOut::Zero;

    for (int ik = 0; ik < NTilesK; ++ik) {
      // [[Consumer Wait]]
      pipeline.consumer_wait(smem_read_pipe);

      warpgroup_fence_operand(tCrC);
      warpgroup_arrive();

#pragma unroll
      for (int k_block = 0; k_block < size<2>(tCrA); ++k_block) {
        gemm(tiled_mma, tCrA(_, _, k_block, smem_read_pipe.index()), tCrB(_, _, k_block, smem_read_pipe.index()),
             tCrC);
        tiled_mma.accumulate_ = GMMA::ScaleOut::One;
      }

      warpgroup_commit_batch();
      warpgroup_wait<0>();

      // [[Consumer Release]]
      pipeline.consumer_release(smem_read_pipe);

      ++smem_read_pipe;
    }

    //
    // EPILOGUE
    //

    if constexpr (use_tma_store_reduce_add) {
      typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
      ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(consumer_tid);
      Tensor tCrC_r2s = r2s_thr_copy_d.retile_S(tCrC);  // (CPY, CPY_M, CPY_N)
      Tensor tCsC_r2s = r2s_thr_copy_d.partition_D(sC); // (CPY, CPY_M, CPY_N)
      copy(r2s_tiled_copy_d, tCrC_r2s, tCsC_r2s);

      tma_store_fence();
      warpgroup_sync(kNumMmaWarpGroups);

      if (consumer_tid == 0) {
        copy(tma_C, tCsC, tCgC);
        tma_store_arrive();
        tma_store_wait<0>();
      }

    } else {

      if constexpr (!IsGemm) {
        // Load C matrix with TMA
        constexpr int tma_transaction_load_c_bytes = kTileM * kTileN * sizeof(ComputeTypeC);
        using SharedStorage_C = SharedStorage_C<ComputeTypeC, SmemLayoutC>;
        SharedStorage_C &smem_c = *reinterpret_cast<SharedStorage_C *>(smem_raw);
        uint64_t &tma_load_c_mbarrier = smem_c.tma_barrier[0];

        auto tCrC_load = make_tensor_like<ComputeTypeC>(tCrC);

        typename Spec::TiledCopyC_S2R s2r_tiled_copy_c;
        ThrCopy s2r_thr_copy_c = s2r_tiled_copy_c.get_slice(consumer_tid);
        Tensor tCsC_s2r = s2r_thr_copy_c.partition_S(sC);     // (CPY, CPY_M, CPY_K)
        Tensor tCrC_s2r = s2r_thr_copy_c.retile_D(tCrC_load); // (CPY, CPY_M, CPY_K)

        if (consumer_tid == 0) {
          initialize_barrier(tma_load_c_mbarrier, /* arrival thread count */ 1);
          cutlass::arch::fence_view_async_shared();

          copy(tma_C.with(tma_load_c_mbarrier), tCgC, tCsC);
          set_barrier_transaction_bytes(tma_load_c_mbarrier, tma_transaction_load_c_bytes);
        }

        warpgroup_sync(kNumMmaWarpGroups);
        wait_barrier(tma_load_c_mbarrier, /* phase */ 0);

        copy(s2r_tiled_copy_c, tCsC_s2r, tCrC_s2r);

// compute with CUDA core
#pragma unroll
        for (int i = 0; i < size(tCrC); ++i) {
          tCrC(i) = tCrC(i) + tCrC_load(i);
        }

        // Important!
        if (consumer_tid == 0) {
          invalidate_barrier(tma_load_c_mbarrier);
        }
        warpgroup_sync(kNumMmaWarpGroups);
      }

      auto tCrD = make_tensor_like<OutType>(tCrC);
      copy(tCrC, tCrD); // Convert precision

      typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
      ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(consumer_tid);
      Tensor tDrD_r2s = r2s_thr_copy_d.retile_S(tCrD);  // (CPY, CPY_M, CPY_N)
      Tensor tDsD_r2s = r2s_thr_copy_d.partition_D(sD); // (CPY, CPY_M, CPY_N)
      copy(r2s_tiled_copy_d, tDrD_r2s, tDsD_r2s);

      tma_store_fence();
      warpgroup_sync(kNumMmaWarpGroups);

      if (consumer_tid == 0) {
        copy(tma_D, tDsD, tDgD);
        tma_store_arrive();
        tma_store_wait<0>();
      }
    }
  } // consumer warp

  // https://forums.developer.nvidia.com/t/an-illegal-instruction-was-encountered/44092/8
  // __syncthreads();

  cluster_sync();
}

__global__ static
__launch_bounds__(decltype(size(TiledMma{}))::value)
void
gemm_device(ProblemShape shape_MNK, CtaTiler cta_tiler,
            TA const* A, AStride dA, ASmemLayout sA_layout, TiledCopyA copy_a,
            TB const* B, BStride dB, BSmemLayout sB_layout, TiledCopyB copy_b,
            TC      * C, CStride dC, TiledMma mma,
            Alpha alpha, Beta beta)
{
  // Preconditions
  CUTE_STATIC_ASSERT_V(rank(shape_MNK) == Int<3>{});                   // (M, N, K)
  CUTE_STATIC_ASSERT_V(rank(cta_tiler) == Int<3>{});                   // (BLK_M, BLK_N, BLK_K)

  CUTE_STATIC_ASSERT_V(size(copy_a) == size(mma));                     // NumThreads
  CUTE_STATIC_ASSERT_V(size(copy_b) == size(mma));                     // NumThreads

  static_assert(is_static<ASmemLayout>::value);
  static_assert(is_static<BSmemLayout>::value);

  CUTE_STATIC_ASSERT_V(size<0>(ASmemLayout{}) == size<0>(cta_tiler));  // BLK_M
  CUTE_STATIC_ASSERT_V(size<0>(BSmemLayout{}) == size<1>(cta_tiler));  // BLK_N
  CUTE_STATIC_ASSERT_V(size<1>(ASmemLayout{}) == size<2>(cta_tiler));  // BLK_K
  CUTE_STATIC_ASSERT_V(size<1>(BSmemLayout{}) == size<2>(cta_tiler));  // BLK_K

  CUTE_STATIC_ASSERT_V(congruent(select<0,2>(shape_MNK), dA));         // dA strides for shape MK
  CUTE_STATIC_ASSERT_V(congruent(select<1,2>(shape_MNK), dB));         // dB strides for shape NK
  CUTE_STATIC_ASSERT_V(congruent(select<0,1>(shape_MNK), dC));         // dC strides for shape MN

  //
  // Full and Tiled Tensors
  //

  // Represent the full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), select<0,2>(shape_MNK), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), select<1,2>(shape_MNK), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), select<0,1>(shape_MNK), dC); // (M,N)

  // Get the appropriate blocks for this thread block
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);              // (m,n,k)
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X,_1>{});  // (BLK_M,BLK_K,k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1,_1>{});  // (BLK_N,BLK_K,k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1, X>{});  // (BLK_M,BLK_N)

  // Shared memory tensors
  extern __shared__ char shared_memory[];
  using SharedStorage = SharedStorage<TA, TB, ASmemLayout, BSmemLayout>;
  SharedStorage& smem = *reinterpret_cast<SharedStorage*>(shared_memory);
  Tensor sA = make_tensor(make_smem_ptr(smem.A.begin()), ASmemLayout{}); // (BLK_M,BLK_K,PIPE)
  Tensor sB = make_tensor(make_smem_ptr(smem.B.begin()), BSmemLayout{}); // (BLK_N,BLK_K,PIPE)

  //
  // Partition the copying of A and B tiles across the threads
  //

  ThrCopy thr_copy_a = copy_a.get_slice(threadIdx.x);
  Tensor tAgA = thr_copy_a.partition_S(gA);                            // (CPY,CPY_M,CPY_K,k)
  Tensor sA_ = as_position_independent_swizzle_tensor(sA);
  Tensor tAsA = thr_copy_a.partition_D(sA_);                           // (CPY,CPY_M,CPY_K,PIPE)

  ThrCopy thr_copy_b = copy_b.get_slice(threadIdx.x);
  Tensor tBgB = thr_copy_b.partition_S(gB);                            // (CPY,CPY_N,CPY_K,k)
  Tensor sB_ = as_position_independent_swizzle_tensor(sB);
  Tensor tBsB = thr_copy_b.partition_D(sB_);                           // (CPY,CPY_N,CPY_K,PIPE)

  CUTE_STATIC_ASSERT_V(size<1>(tAgA) == size<1>(tAsA));                // CPY_M
  CUTE_STATIC_ASSERT_V(size<2>(tAgA) == size<2>(tAsA));                // CPY_K
  CUTE_STATIC_ASSERT_V(size<1>(tBgB) == size<1>(tBsB));                // CPY_N
  CUTE_STATIC_ASSERT_V(size<2>(tBgB) == size<2>(tBsB));                // CPY_K

  //
  // PREFETCH
  //

  // auto K_PIPE_MAX = size<3>(tAsA);

  // // Total count of tiles
  // int k_tile_count = size<3>(tAgA);
  // // Current tile index in gmem to read from
  // int k_tile_next = 0;

  // // Start async loads for all pipes but the last
  // CUTE_UNROLL
  // for (int k_pipe = 0; k_pipe < K_PIPE_MAX-1; ++k_pipe) {
  //   copy(copy_a, tAgA(_,_,_,k_tile_next), tAsA(_,_,_,k_pipe));
  //   copy(copy_b, tBgB(_,_,_,k_tile_next), tBsB(_,_,_,k_pipe));
  //   cp_async_fence();
  //   --k_tile_count;
  //   if (k_tile_count > 0) { ++k_tile_next; }
  // }

  //
  // Define A/B partitioning and C accumulators
  //

  ThrMMA thr_mma = mma.get_slice(threadIdx.x);
  Tensor tCsA = thr_mma.partition_A(sA);                               // (MMA,MMA_M,MMA_K,PIPE)
  Tensor tCsB = thr_mma.partition_B(sB);                               // (MMA,MMA_N,MMA_K,PIPE)
  Tensor tCgC = thr_mma.partition_C(gC);                               // (MMA,MMA_M,MMA_N)

  // Allocate registers for pipelining
  Tensor tCrA = thr_mma.make_fragment_A(tCsA);                         // (MMA,MMA_M,MMA_K,PIPE)
  Tensor tCrB = thr_mma.make_fragment_B(tCsB);                         // (MMA,MMA_N,MMA_K,PIPE)
  // Allocate the accumulators -- same size as the projected data
  Tensor tCrC = thr_mma.make_fragment_C(tCgC);                         // (MMA,MMA_M,MMA_N)

  CUTE_STATIC_ASSERT_V((size<1>(tCgC) == size<1>(tCsA)));              // MMA_M
  CUTE_STATIC_ASSERT_V((size<2>(tCgC) == size<1>(tCsB)));              // MMA_N
  CUTE_STATIC_ASSERT_V((size<2>(tCsA) == size<2>(tCsB)));              // MMA_K

  // Clear the accumulators
  clear(tCrC);

#if 0
  if(thread0()) {
    print("  mA : "); print(  mA); print("\n");
    print("  gA : "); print(  gA); print("\n");
    print("  sA : "); print(  sA); print("\n");
    print("tAgA : "); print(tAgA); print("\n");
    print("tAsA : "); print(tAsA); print("\n");
  }
#endif

#if 0
  if(thread0()) {
    print("  mB : "); print(  mB); print("\n");
    print("  gB : "); print(  gB); print("\n");
    print("  sB : "); print(  sB); print("\n");
    print("tBgB : "); print(tBgB); print("\n");
    print("tBsB : "); print(tBsB); print("\n");
  }
#endif

#if 0
  if(thread0()) {
    print("  mC : "); print(  mC); print("\n");
    print("  gC : "); print(  gC); print("\n");
    print("tCsA : "); print(tCsA); print("\n");
    print("tCsB : "); print(tCsB); print("\n");
    print("tCgC : "); print(tCgC); print("\n");
    print("tCrA : "); print(tCrA); print("\n");
    print("tCrB : "); print(tCrB); print("\n");
    print("tCrC : "); print(tCrC); print("\n");
  }
#endif

#if 1

  // Total number of k-tiles
  auto K_TILE_MAX  = size<3>(tAgA);
  // Number of pipelined k-tiles in smem
  auto K_PIPE_MAX  = size<3>(tAsA);

  //
  // PREFETCH
  //

  // Prefetch all but the last
  CUTE_UNROLL
  for (int k = 0; k < K_PIPE_MAX-1; ++k)
  {
    copy(copy_a, tAgA(_,_,_,k), tAsA(_,_,_,k));
    copy(copy_b, tBgB(_,_,_,k), tBsB(_,_,_,k));
    cp_async_fence();
  }

  // Clear the accumulators
  clear(tCrC);

  __syncthreads();

  //
  // PIPELINED MAIN LOOP
  //

  // Current pipe to read from
  int k_pipe_read  = 0;
  // Current pipe to write to
  int k_pipe_write = K_PIPE_MAX-1;

  CUTE_NO_UNROLL
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile)
  {
    int k_tile_next = k_tile + (K_PIPE_MAX-1);
    k_tile_next = (k_tile_next >= K_TILE_MAX) ? K_TILE_MAX-1 : k_tile_next;

    //
    // Copy gmem to smem for k_tile_write
    //

    copy(copy_a, tAgA(_,_,_,k_tile_next), tAsA(_,_,_,k_pipe_write));
    copy(copy_b, tBgB(_,_,_,k_tile_next), tBsB(_,_,_,k_pipe_write));
    cp_async_fence();

    // Advance k_pipe_write
    ++k_pipe_write;
    k_pipe_write = (k_pipe_write == K_PIPE_MAX) ? 0 : k_pipe_write;

    //
    // Compute on k_tile
    //

    // Wait on all cp.async -- optimize by pipelining to overlap GMEM reads
    cp_async_wait<0>();

    warpgroup_fence_operand(tCrC);
    warpgroup_arrive();
    // (V,M,K) x (V,N,K) => (V,M,N)
    cute::gemm(mma, tCrA(_,_,_,k_pipe_read), tCrB(_,_,_,k_pipe_read), tCrC);
    warpgroup_commit_batch();
    /// Wait on the GMMA barrier for K_PIPE_MMAS (or fewer) outstanding to ensure smem_pipe_write is consumed
    warpgroup_wait<0>();
    warpgroup_fence_operand(tCrC);

    // Advance k_pipe_read
    ++k_pipe_read;
    k_pipe_read = (k_pipe_read == K_PIPE_MAX) ? 0 : k_pipe_read;
  }

#endif

  //
  // Epilogue
  //

  axpby(alpha, tCrC, beta, tCgC);
}

__global__ static
__launch_bounds__(decltype(size(TiledMma{}))::value)
void
gemm_device(ProblemShape shape_MNK, CtaTiler cta_tiler,
            TA const* A, CUTLASS_GRID_CONSTANT TmaA const tma_a,
            TB const* B, CUTLASS_GRID_CONSTANT TmaB const tma_b,
            TC      * C, CStride dC, TiledMma mma,
            Alpha alpha, Beta beta)
{
  // Preconditions
  CUTE_STATIC_ASSERT_V(rank(shape_MNK) == Int<3>{});                   // (M, N, K)
  CUTE_STATIC_ASSERT_V(rank(cta_tiler) == Int<3>{});                   // (BLK_M, BLK_N, BLK_K)

  static_assert(is_static<SmemLayoutA>::value);
  static_assert(is_static<SmemLayoutB>::value);

  CUTE_STATIC_ASSERT_V(size<0>(SmemLayoutA{}) == size<0>(cta_tiler));  // BLK_M
  CUTE_STATIC_ASSERT_V(size<0>(SmemLayoutB{}) == size<1>(cta_tiler));  // BLK_N
  CUTE_STATIC_ASSERT_V(size<1>(SmemLayoutA{}) == size<2>(cta_tiler));  // BLK_K
  CUTE_STATIC_ASSERT_V(size<1>(SmemLayoutB{}) == size<2>(cta_tiler));  // BLK_K

  CUTE_STATIC_ASSERT_V(congruent(select<0,1>(shape_MNK), dC));         // dC strides for shape MN

  //
  // Full and Tiled Tensors
  //

  // Represent the full tensors
  auto [M, N, K] = shape_MNK;
  Tensor mA = tma_a.get_tma_tensor(make_shape(M,K));                   // (M,K) TMA Tensor
  Tensor mB = tma_b.get_tma_tensor(make_shape(N,K));                   // (N,K) TMA Tensor
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M,N), dC);      // (M,N)

  // Get the appropriate blocks for this thread block
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);              // (m,n,k)
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X,_1>{});  // (BLK_M,BLK_K,k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1,_1>{});  // (BLK_N,BLK_K,k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1, X>{});  // (BLK_M,BLK_N)

  // Shared memory tensors
  extern __shared__ char shared_memory[];
  using SharedStorage = SharedStorage<TA, TB, SmemLayoutA, SmemLayoutB>;
  SharedStorage& smem = *reinterpret_cast<SharedStorage*>(shared_memory);
  Tensor sA = make_tensor(make_smem_ptr(smem.A.begin()), SmemLayoutA{}); // (BLK_M,BLK_K,PIPE)
  Tensor sB = make_tensor(make_smem_ptr(smem.B.begin()), SmemLayoutB{}); // (BLK_N,BLK_K,PIPE)

  //
  // Partition the copying of A and B tiles
  //
  // TUTORIAL:
  //   These are TMA partitionings, which have a dedicated custom partitioner.
  //   The Int<0>, Layout<_1> indicates that the TMAs are not multicasted.
  //     Any multicasting must be in conformance with tma_x constructed with make_tma_atom on host.
  //   The group_modes<0,2> transforms the (X,Y,Z)-shaped tensors into ((X,Y),Z)-shaped tensors
  //     with the understanding that the TMA is responsible for everything in mode-0.
  //   The tma_partition reorders and offsets mode-0 according to the tma_x atom and the multicast info.
  //

  auto [tAgA, tAsA] = tma_partition(tma_a, Int<0>{}, Layout<_1>{},
                                    group_modes<0,2>(sA), group_modes<0,2>(gA));  // (TMA,k) and (TMA,PIPE)

  auto [tBgB, tBsB] = tma_partition(tma_b, Int<0>{}, Layout<_1>{},
                                    group_modes<0,2>(sB), group_modes<0,2>(gB));  // (TMA,k) and (TMA,PIPE)

  // The TMA is responsible for copying everything in mode-0 of tAsA and tBsB
  constexpr int tma_transaction_bytes = sizeof(make_tensor_like(tensor<0>(tAsA)))
                                      + sizeof(make_tensor_like(tensor<0>(tBsB)));

  //
  // PREFETCH
  //

  auto K_PIPE_MAX = size<1>(tAsA);

  // Total count of tiles
  int k_tile_count = size<1>(tAgA);
  // Current tile index in gmem to read from
  int k_tile = 0;

  // Initialize Barriers
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int lane_predicate = cute::elect_one_sync();
  uint64_t* producer_mbar = smem.tma_barrier;
  uint64_t* consumer_mbar = smem.mma_barrier;

  using ProducerBarType = cutlass::arch::ClusterTransactionBarrier;  // TMA
  using ConsumerBarType = cutlass::arch::ClusterBarrier;             // MMA
  CUTE_UNROLL
  for (int pipe = 0; pipe < K_PIPE_MAX; ++pipe) {
    if ((warp_idx == 0) && lane_predicate) {
      ProducerBarType::init(&producer_mbar[pipe],   1);
      ConsumerBarType::init(&consumer_mbar[pipe], 128);
    }
  }
  // Ensure barrier init is complete on all CTAs
  cluster_sync();

  // Start async loads for all pipes
  CUTE_UNROLL
  for (int pipe = 0; pipe < K_PIPE_MAX; ++pipe)
  {
    if ((warp_idx == 0) && lane_predicate)
    {
      // Set expected Tx Bytes after each reset / init
      ProducerBarType::arrive_and_expect_tx(&producer_mbar[pipe], tma_transaction_bytes);
      copy(tma_a.with(producer_mbar[pipe]), tAgA(_,k_tile), tAsA(_,pipe));
      copy(tma_b.with(producer_mbar[pipe]), tBgB(_,k_tile), tBsB(_,pipe));
    }
    --k_tile_count;
    ++k_tile;
  }

  //
  // Define A/B partitioning and C accumulators
  //
  // TUTORIAL:
  //   The tCrA and tCrB are actually Tensors of MMA Descriptors constructed as views of SMEM.
  //   The MMA Descriptor generation is automatic via inspection and validation of the SMEM Layouts.
  //   Because the MMA reads directly from SMEM and the fragments are descriptors rather than registers,
  //     there is no need for copy(tCsA, tCrA) in the mainloop.
  //

  ThrMMA thr_mma = mma.get_thread_slice(threadIdx.x);
  Tensor tCsA = thr_mma.partition_A(sA);                               // (MMA,MMA_M,MMA_K,PIPE)
  Tensor tCsB = thr_mma.partition_B(sB);                               // (MMA,MMA_N,MMA_K,PIPE)
  Tensor tCgC = thr_mma.partition_C(gC);                               // (MMA,MMA_M,MMA_N)

  // Allocate accumulators and clear them
  Tensor tCrC = thr_mma.make_fragment_C(tCgC);                         // (MMA,MMA_M,MMA_N)
  clear(tCrC);

  // Allocate "fragments"
  Tensor tCrA = thr_mma.make_fragment_A(tCsA);                         // (MMA,MMA_M,MMA_K,PIPE)
  Tensor tCrB = thr_mma.make_fragment_B(tCsB);                         // (MMA,MMA_N,MMA_K,PIPE)

  //
  // PIPELINED MAIN LOOP
  //
  // TUTORIAL:
  //   Rather than interleaving the stages and instructions like in SM70 and SM80,
  //     the SM90 mainloops rely on explicit producer-consumer synchronization
  //     on the purely async instructions TMA and MMA.
  //   More advanced pipeline and warp-specialization strategies are available in CUTLASS mainloops.
  //

  // A PipelineState is a circular pipe index [.index()] and a pipe phase [.phase()]
  //   that flips each cycle through K_PIPE_MAX.
  auto write_state = cutlass::PipelineState<K_PIPE_MAX>();             // TMA writes
  auto read_state  = cutlass::PipelineState<K_PIPE_MAX>();             // MMA  reads

  CUTE_NO_UNROLL
  while (k_tile_count > -K_PIPE_MAX)
  {
    // Wait for Producer to complete
    int read_pipe = read_state.index();
    ProducerBarType::wait(&producer_mbar[read_pipe], read_state.phase());

    // MMAs to cover 1 K_TILE
    warpgroup_arrive();
    gemm(mma, tCrA(_,_,_,read_pipe), tCrB(_,_,_,read_pipe), tCrC);     // (V,M) x (V,N) => (V,M,N)
    warpgroup_commit_batch();

    // Wait for all MMAs in a K_TILE to complete
    warpgroup_wait<0>();

    // Notify that consumption is done
    ConsumerBarType::arrive(&consumer_mbar[read_pipe]);
    ++read_state;

    // Only issue new TMA copies if there are more tiles to fetch
    if ((warp_idx == 0) && lane_predicate && (k_tile_count > 0))
    {
      int pipe = write_state.index();
      // Wait for Consumer to complete consumption
      ConsumerBarType::wait(&consumer_mbar[pipe], write_state.phase());
      // Set expected Tx Bytes after each reset / init
      ProducerBarType::arrive_and_expect_tx(&producer_mbar[pipe], tma_transaction_bytes);
      copy(tma_a.with(producer_mbar[pipe]), tAgA(_,k_tile), tAsA(_,pipe));
      copy(tma_b.with(producer_mbar[pipe]), tBgB(_,k_tile), tBsB(_,pipe));
      ++write_state;
    }
    --k_tile_count;
    ++k_tile;
  }

  //
  // Epilogue (unpredicated)
  //

  axpby(alpha, tCrC, beta, tCgC);
}

__global__ __launch_bounds__(Spec::kThreadNum) void
#if !(USE_CUTLASS_LAUNCHER)
    __cluster_dims__(Spec::kClusterDimX, Spec::kClusterDimY, Spec::kClusterDimZ)
#endif
        warpgroup_mma(__grid_constant__ TMA_A const tma_A,
                      __grid_constant__ TMA_B const tma_B,
                      __grid_constant__ TMA_C const tma_C,
                      __grid_constant__ TMA_D const tma_D,
                      int M,
                      int N,
                      int K) {
  using namespace cute;

  using X = Underscore;
  using OutType = typename Spec::OutType;
  using ComputeTypeA = typename Spec::ComputeTypeA;
  using ComputeTypeB = typename Spec::ComputeTypeB;
  using ComputeTypeC = typename Spec::ComputeTypeC;
  using SmemLayoutA = typename Spec::SmemLayoutA;
  using SmemLayoutB = typename Spec::SmemLayoutB;
  using SmemLayoutC = typename Spec::SmemLayoutC;
  using SmemLayoutD = typename Spec::SmemLayoutD;

  constexpr int kTileM = Spec::kTileM;
  constexpr int kTileN = Spec::kTileN;
  constexpr int kTileK = Spec::kTileK;
  constexpr int kStages = Spec::kStages;
  constexpr int kThreadNum = Spec::kThreadNum;
  constexpr int kWarpgroupNum = Spec::kWarpgroupNum;
  constexpr int kClusterSize = Spec::kClusterSize;

  extern __shared__ __align__(1024) uint8_t smem_raw[];

  using SharedStorage = SharedStorage_AB<ComputeTypeA, ComputeTypeB, SmemLayoutA, SmemLayoutB>;
  SharedStorage &smem = *reinterpret_cast<SharedStorage *>(smem_raw);

  auto *Aptr_smem = smem.A.begin();
  auto *Bptr_smem = smem.B.begin();
  uint8_t *Cptr_smem = smem_raw;
  uint8_t *Dptr_smem = smem_raw;

  int tid = threadIdx.x;
  int bidx = blockIdx.x;
  int bidy = blockIdx.y;

  Tensor mA = tma_A.get_tma_tensor(make_shape(M, K));
  Tensor mB = tma_B.get_tma_tensor(make_shape(N, K));
  Tensor mC = tma_C.get_tma_tensor(make_shape(M, N));
  Tensor mD = tma_D.get_tma_tensor(make_shape(M, N));

  auto tiler = make_tile(Int<kTileM>{}, Int<kTileN>{}, Int<kTileK>{});
  auto coord = make_coord(bidy, bidx, _);

  Tensor gA = local_tile(mA, tiler, coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, K_TILES)
  Tensor gB = local_tile(mB, tiler, coord, Step<X, _1, _1>{}); // (BLK_N, BLK_K, K_TILES)
  Tensor gC = local_tile(mC, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)
  Tensor gD = local_tile(mD, tiler, coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  Tensor sA = make_tensor(make_smem_ptr((ComputeTypeA *)Aptr_smem), SmemLayoutA{}); // (BLK_M, BLK_K, kStages)
  Tensor sB = make_tensor(make_smem_ptr((ComputeTypeB *)Bptr_smem), SmemLayoutB{}); // (BLK_N, BLK_K, kStages)
  Tensor sC = make_tensor(make_smem_ptr((ComputeTypeC *)Cptr_smem), SmemLayoutC{}); // (BLK_M, BLK_N)
  Tensor sD = make_tensor(make_smem_ptr((OutType *)Dptr_smem), SmemLayoutD{});      // (BLK_M, BLK_N)

  // Define the CTA-in-cluster Layout and Coord
  uint32_t block_rank_in_cluster = cute::block_rank_in_cluster();
  auto cta_layout_mnk = make_layout(typename Spec::ClusterShape{});
  auto cta_coord_mnk = cta_layout_mnk.get_flat_coord(block_rank_in_cluster);

  // TMA Multicast Masks
  uint16_t mcast_mask_a = create_tma_multicast_mask<0>(cta_layout_mnk, cta_coord_mnk);
  uint16_t mcast_mask_b = create_tma_multicast_mask<1>(cta_layout_mnk, cta_coord_mnk);

  auto [tAgA, tAsA] = tma_partition(tma_A,
                                    get<0>(cta_coord_mnk), // The CTA coordinate along N mode of the cluster
                                    make_layout(size<0>(cta_layout_mnk)), // The CTA layout along N mode of the cluster
                                    group_modes<0, 2>(sA), group_modes<0, 2>(gA)); // (TMA,K_TILES) and (TMA,kStages)
  auto [tBgB, tBsB] = tma_partition(tma_B,
                                    get<1>(cta_coord_mnk), // The CTA coordinate along M mode of the cluster
                                    make_layout(size<1>(cta_layout_mnk)), // The CTA layout along M mode of the cluster
                                    group_modes<0, 2>(sB), group_modes<0, 2>(gB)); // (TMA,K_TILES) and (TMA,kStages)
  auto [tCgC, tCsC] = tma_partition(tma_C, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sC),
                                    group_modes<0, 2>(gC)); // (TMA,K_TILES) and (TMA)
  auto [tDgD, tDsD] = tma_partition(tma_D, Int<0>{}, Layout<_1>{}, group_modes<0, 2>(sD),
                                    group_modes<0, 2>(gD)); // (TMA,K_TILES) and (TMA)

  constexpr int tma_transaction_bytes =
      kTileM * kTileK * sizeof(ComputeTypeA) + kTileN * kTileK * sizeof(ComputeTypeB);

  typename Spec::TiledMMA tiled_mma;
  ThrMMA thr_mma = tiled_mma.get_slice(tid);

  Tensor tCrA = thr_mma.partition_fragment_A(sA); // (MMA, MMA_M, MMA_K, kStages)
  Tensor tCrB = thr_mma.partition_fragment_B(sB); // (MMA, MMA_N, MMA_K, kStages)
  Tensor tCrC = thr_mma.partition_fragment_C(sC); // (MMA, MMA_M, MMA_N)

  //
  // PREFETCH
  //

  int NTilesK = ceil_div(K, kTileK);

  int warpgroup_idx = cutlass::canonical_warp_group_idx();
  int warpgroup_tid = tid % cutlass::NumThreadsPerWarpGroup;
  int warp_idx = cutlass::canonical_warp_idx_sync();
  int lane_predicate = cute::elect_one_sync();
  uint64_t *tma_load_mbarrier = smem.tma_barrier;
  uint64_t *mma_consume_mbarrier = smem.mma_barrier;

  // Prefetch TMA tensor to L2 cache
  if ((warp_idx == 0) && lane_predicate) {
    cute::prefetch_tma_descriptor(tma_A.get_tma_descriptor());
    cute::prefetch_tma_descriptor(tma_B.get_tma_descriptor());
    if constexpr (!IsGemm) {
      cute::prefetch_tma_descriptor(tma_C.get_tma_descriptor());
    }
  }

  // Init TMA load barrier
  if ((warp_idx == 0) && lane_predicate) {
#pragma unroll
    for (int pipe = 0; pipe < kStages; ++pipe) {
      initialize_barrier(tma_load_mbarrier[pipe], /* arrival count */ 1);
      initialize_barrier(mma_consume_mbarrier[pipe], /* arrival count */ kWarpgroupNum * kClusterSize);
    }

    // Make initialized barrier visible in async proxy.
    cutlass::arch::fence_view_async_shared();
  }

  // Make sure all threads across all CTAs in Cluster observe barrier initialization.
  if constexpr (Spec::kClusterSize > 1) {
    cluster_sync();
  } else {
    __syncthreads();
  }

#pragma unroll
  for (int pipe = 0; pipe < kStages; ++pipe) {
    if ((warp_idx == 0) && lane_predicate && (pipe < NTilesK)) {
      copy(tma_A.with(tma_load_mbarrier[pipe], mcast_mask_a), tAgA(_, pipe), tAsA(_, pipe));
      copy(tma_B.with(tma_load_mbarrier[pipe], mcast_mask_b), tBgB(_, pipe), tBsB(_, pipe));

      // Arrive on the barrier and tell how many bytes are expected to come in.
      set_barrier_transaction_bytes(tma_load_mbarrier[pipe], tma_transaction_bytes);
    }
  }

  //
  // MAINLOOP
  //

  int gmem_read_pipe = kStages;
  int smem_write_pipe = 0;
  int smem_read_pipe = 0;
  int tma_phase_bit = 1;
  int mma_phase_bit = 1;

  tiled_mma.accumulate_ = GMMA::ScaleOut::Zero;

  for (int ik = 0; ik < NTilesK; ++ik) {
    if (smem_read_pipe == 0) {
      tma_phase_bit ^= 1;
    }
    wait_barrier(tma_load_mbarrier[smem_read_pipe], /* phase */ tma_phase_bit);

    warpgroup_fence_operand(tCrC);
    warpgroup_arrive();

#pragma unroll
    for (int k_block = 0; k_block < size<2>(tCrA); ++k_block) {
      gemm(tiled_mma, tCrA(_, _, k_block, smem_read_pipe), tCrB(_, _, k_block, smem_read_pipe), tCrC);
      tiled_mma.accumulate_ = GMMA::ScaleOut::One;
    }

    warpgroup_commit_batch();
    warpgroup_wait<0>();

    if (warpgroup_tid < kClusterSize) {
      arrive_barrier_cluster(mma_consume_mbarrier[smem_read_pipe], warpgroup_tid);
    }

    ++smem_read_pipe;
    smem_read_pipe = (smem_read_pipe == kStages) ? 0 : smem_read_pipe;

    if ((warp_idx == 0) && lane_predicate && (gmem_read_pipe < NTilesK)) {
      if (smem_write_pipe == 0) {
        mma_phase_bit ^= 1;
      }
      wait_barrier(mma_consume_mbarrier[smem_write_pipe], /* phase */ mma_phase_bit);

      copy(tma_A.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_a), tAgA(_, gmem_read_pipe),
           tAsA(_, smem_write_pipe));
      copy(tma_B.with(tma_load_mbarrier[smem_write_pipe], mcast_mask_b), tBgB(_, gmem_read_pipe),
           tBsB(_, smem_write_pipe));

      // Arrive on the barrier and tell how many bytes are expected to come in.
      set_barrier_transaction_bytes(tma_load_mbarrier[smem_write_pipe], tma_transaction_bytes);

      ++gmem_read_pipe;
      ++smem_write_pipe;
      smem_write_pipe = (smem_write_pipe == kStages) ? 0 : smem_write_pipe;
    }
  }

  __syncthreads();

  // Important!
  if ((warp_idx == 0) && lane_predicate) {
#pragma unroll
    for (int pipe = 0; pipe < kStages; ++pipe) {
      invalidate_barrier(tma_load_mbarrier[pipe]);
      invalidate_barrier(mma_consume_mbarrier[pipe]);
    }
  }
  __syncthreads();

  //
  // EPILOGUE
  //

  if constexpr (use_tma_store_reduce_add) {
    typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
    ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(tid);
    Tensor tCrC_r2s = r2s_thr_copy_d.retile_S(tCrC);  // (CPY, CPY_M, CPY_N)
    Tensor tCsC_r2s = r2s_thr_copy_d.partition_D(sC); // (CPY, CPY_M, CPY_N)
    copy(r2s_tiled_copy_d, tCrC_r2s, tCsC_r2s);

    tma_store_fence();
    __syncthreads();

    if ((warp_idx == 0) && lane_predicate) {
      copy(tma_C, tCsC, tCgC);
      tma_store_arrive();
      tma_store_wait<0>();
    }

  } else {

    if constexpr (!IsGemm) {
      // Load C matrix with TMA
      constexpr int tma_transaction_load_c_bytes = kTileM * kTileN * sizeof(ComputeTypeC);
      using SharedStorage_C = SharedStorage_C<ComputeTypeC, SmemLayoutC>;
      SharedStorage_C &smem_c = *reinterpret_cast<SharedStorage_C *>(smem_raw);
      uint64_t &tma_load_c_mbarrier = smem_c.tma_barrier[0];

      auto tCrC_load = make_tensor_like<ComputeTypeC>(tCrC);

      typename Spec::TiledCopyC_S2R s2r_tiled_copy_c;
      ThrCopy s2r_thr_copy_c = s2r_tiled_copy_c.get_slice(tid);
      Tensor tCsC_s2r = s2r_thr_copy_c.partition_S(sC);     // (CPY, CPY_M, CPY_K)
      Tensor tCrC_s2r = s2r_thr_copy_c.retile_D(tCrC_load); // (CPY, CPY_M, CPY_K)

      if ((warp_idx == 0) && lane_predicate) {
        initialize_barrier(tma_load_c_mbarrier, /* arrival thread count */ 1);
        cutlass::arch::fence_view_async_shared();

        copy(tma_C.with(tma_load_c_mbarrier), tCgC, tCsC);
        set_barrier_transaction_bytes(tma_load_c_mbarrier, tma_transaction_load_c_bytes);
      }

      __syncthreads();
      wait_barrier(tma_load_c_mbarrier, /* phase */ 0);

      copy(s2r_tiled_copy_c, tCsC_s2r, tCrC_s2r);

// compute with CUDA core
#pragma unroll
      for (int i = 0; i < size(tCrC); ++i) {
        tCrC(i) = tCrC(i) + tCrC_load(i);
      }

      // Important!
      if ((warp_idx == 0) && lane_predicate) {
        invalidate_barrier(tma_load_c_mbarrier);
      }
      __syncthreads();
    }

    auto tCrD = make_tensor_like<OutType>(tCrC);
    copy(tCrC, tCrD); // Convert precision

    typename Spec::TiledCopyD_R2S r2s_tiled_copy_d;
    ThrCopy r2s_thr_copy_d = r2s_tiled_copy_d.get_slice(tid);
    Tensor tDrD_r2s = r2s_thr_copy_d.retile_S(tCrD);  // (CPY, CPY_M, CPY_N)
    Tensor tDsD_r2s = r2s_thr_copy_d.partition_D(sD); // (CPY, CPY_M, CPY_N)
    copy(r2s_tiled_copy_d, tDrD_r2s, tDsD_r2s);

    tma_store_fence();
    __syncthreads();

    if ((warp_idx == 0) && lane_predicate) {
      copy(tma_D, tDsD, tDgD);
      tma_store_arrive();
      tma_store_wait<0>();
    }
  }

  // In multicast scenario, we MUST end the kernel with cluster_sync to ensure that
  // CTA in the cluster doesn’t exit prematurely.
  // 也就是说，必须两个两个退出，否则分配了奇数个 block，很可能最后的单个 block 无法凑成 cluster。
  cluster_sync();
}
